#requires -Version 5.1
[CmdletBinding()]
param(
    [switch]$VerifyDependencies,
    [switch]$CreateLauncher,
    [Parameter(DontShow=$true)][string]$RuntimeInstance,
    [string]$DatabasePath,
    [string]$ImportHtmlPath,
    [string]$OpenEvidencePackage,
    [string]$ScanPath,
    [switch]$CreateDatabase,
    [switch]$ScanArchives,
    [string]$ResumeScanId,
    [ValidateRange(1,8)][int]$WorkerCount=4,
    [ValidateSet('Quick','Deep','Custom')][string]$ScanMode='Quick',
    [string[]]$Extensions
)
$ErrorActionPreference='Stop'
# The outer process never loads private assemblies. It can delete them after the runtime exits.
function ConvertTo-ReviewerArgument([string]$Value) {
    $text=[Text.StringBuilder]::new();[void]$text.Append('"');$slashes=0
    foreach($character in $Value.ToCharArray()){
        if($character -eq '\'){$slashes++;continue}
        if($character -eq '"'){[void]$text.Append([char]'\',2*$slashes+1)}else{[void]$text.Append([char]'\',$slashes)}
        [void]$text.Append($character);$slashes=0
    }
    [void]$text.Append([char]'\',2*$slashes);[void]$text.Append('"');return $text.ToString()
}
function Get-ReviewerRuntimeRoot { return Join-Path ([IO.Path]::GetTempPath()) 'MediaComplianceReviewer' }
function New-ReviewerRuntimeDirectory([string]$Root) {
    $base=[IO.Path]::GetFullPath($Root).TrimEnd('\')
    if([IO.Path]::GetFileName($base) -cne 'MediaComplianceReviewer'){throw 'Invalid private temporary root.'}
    [IO.Directory]::CreateDirectory($base) | Out-Null
    if(([IO.File]::GetAttributes($base) -band [IO.FileAttributes]::ReparsePoint)){throw 'The private temporary root cannot be a junction or symbolic link.'}
    $directory=Join-Path $base ([Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($directory) | Out-Null;return $directory
}
function Test-ReviewerRuntimePath([string]$Root,[string]$Directory) {
    try{
        $base=[IO.Path]::GetFullPath($Root).TrimEnd('\');$path=[IO.Path]::GetFullPath($Directory).TrimEnd('\');$guid=[Guid]::Empty
        if([IO.Path]::GetFileName($base) -cne 'MediaComplianceReviewer' -or [IO.Path]::GetDirectoryName($path) -ine $base -or -not [Guid]::TryParseExact([IO.Path]::GetFileName($path),'N',[ref]$guid)){return $false}
        foreach($item in @($base,$path,(Join-Path $path 'owner.marker'))){if(([IO.File]::GetAttributes($item) -band [IO.FileAttributes]::ReparsePoint) -ne 0){return $false}}
        $marker=Join-Path $path 'owner.marker';if(([IO.FileInfo]::new($marker)).Length -gt 128){return $false}
        return [IO.File]::ReadAllText($marker) -cin @('MediaComplianceReviewer-owned-v1','MediaComplianceReviewer-owned-v2')
    }catch{return $false}
}
function Remove-ReviewerRuntime([string]$Root,[string]$Directory,[int]$BudgetMilliseconds=0) {
    $leases=[Collections.Generic.List[IDisposable]]::new();$clock=[Diagnostics.Stopwatch]::StartNew();$done=$false
    try{
        $base=[IO.Path]::GetFullPath($Root).TrimEnd('\');$path=[IO.Path]::GetFullPath($Directory).TrimEnd('\');$guid=[Guid]::Empty
        if([IO.Path]::GetFileName($base) -cne 'MediaComplianceReviewer' -or [IO.Path]::GetDirectoryName($path) -ine $base -or -not [Guid]::TryParseExact([IO.Path]::GetFileName($path),'N',[ref]$guid)){return $false}
        if(-not [IO.Directory]::Exists($path)){return $true}
        if(-not (Test-ReviewerRuntimePath $base $path)){return $false}
        foreach($name in @('launcher.lease','instance.lease')){
            $file=Join-Path $path $name
            if([IO.File]::Exists($file) -and ([IO.File]::GetAttributes($file) -band [IO.FileAttributes]::ReparsePoint)){return $false}
            $leases.Add([IO.File]::Open($file,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None))
        }
        $directories=[Collections.Generic.List[string]]::new();$files=[Collections.Generic.List[string]]::new();$pending=[Collections.Generic.Stack[string]]::new();$pending.Push($path);$boundary=$path+'\'
        # Validate the complete bounded tree first. Never traverse junctions or symbolic links.
        while($pending.Count){
            $current=$pending.Pop();$directories.Add($current)
            foreach($entry in [IO.DirectoryInfo]::new($current).EnumerateFileSystemInfos()){
                if($BudgetMilliseconds -gt 0 -and $clock.ElapsedMilliseconds -gt $BudgetMilliseconds){return $false}
                if($directories.Count+$files.Count+$pending.Count -ge 8192 -or -not $entry.FullName.StartsWith($boundary,[StringComparison]::OrdinalIgnoreCase) -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){return $false}
                if($entry.Attributes -band [IO.FileAttributes]::Directory){$pending.Push($entry.FullName)}else{$files.Add($entry.FullName)}
            }
        }
        foreach($file in $files){
            if([IO.Path]::GetDirectoryName($file) -ieq $path -and [IO.Path]::GetFileName($file) -in @('owner.marker','launcher.lease','instance.lease')){continue}
            if($BudgetMilliseconds -gt 0 -and $clock.ElapsedMilliseconds -gt $BudgetMilliseconds){return $false}
            $ancestor=[IO.Path]::GetDirectoryName($file)
            while($ancestor.Length -ge $base.Length){if(([IO.File]::GetAttributes($ancestor) -band [IO.FileAttributes]::ReparsePoint)){return $false};$ancestor=[IO.Path]::GetDirectoryName($ancestor)}
            if(([IO.File]::GetAttributes($file) -band [IO.FileAttributes]::ReparsePoint)){return $false}
            [IO.File]::Delete($file)
        }
        for($i=$directories.Count-1;$i -gt 0;$i--){if(-not (Test-ReviewerRuntimePath $base $path) -or ([IO.File]::GetAttributes($directories[$i]) -band [IO.FileAttributes]::ReparsePoint)){return $false};[IO.Directory]::Delete($directories[$i],$false)}
        $done=$true
    }catch{return $false}finally{foreach($lease in $leases){$lease.Dispose()}}
    if($done){
        try{foreach($name in @('launcher.lease','instance.lease','owner.marker')){[IO.File]::Delete((Join-Path $path $name))};[IO.Directory]::Delete($path,$false);return $true}catch{return $false}
    }
    return $false
}
function Save-ReviewerDiagnostic([string]$Source,[string]$Text) {
    try{
        $profileRoot=[Environment]::GetEnvironmentVariable('LOCALAPPDATA');if(-not $profileRoot){$profileRoot=[Environment]::GetFolderPath('LocalApplicationData')}
        $logs=Join-Path $profileRoot 'MediaComplianceReviewer\Logs';[IO.Directory]::CreateDirectory($logs) | Out-Null
        $file=Join-Path $logs ('startup-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss')+'-'+[Guid]::NewGuid().ToString('N')+'.log')
        if($Source -and [IO.File]::Exists($Source)){$inputFile=[IO.File]::Open($Source,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite);try{$bytes=[byte[]]::new(65536);$count=$inputFile.Read($bytes,0,$bytes.Length);$output=[IO.File]::Open($file,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$output.Write($bytes,0,$count)}finally{$output.Dispose()}}finally{$inputFile.Dispose()}}
        else{if($Text.Length -gt 8192){$Text=$Text.Substring(0,8192)};[IO.File]::WriteAllText($file,$Text,[Text.UTF8Encoding]::new($false))}
        foreach($old in @(Get-ChildItem -LiteralPath $logs -Filter 'startup-*.log' -File | Sort-Object LastWriteTimeUtc -Descending | Select-Object -Skip 5)){if(-not ($old.Attributes -band [IO.FileAttributes]::ReparsePoint)){[IO.File]::Delete($old.FullName)}}
        return $file
    }catch{return $null}
}
function New-ReviewerLauncher([string]$ScriptPath) {
    $scriptFile=[IO.Path]::GetFullPath($ScriptPath);if(-not [IO.File]::Exists($scriptFile) -or [IO.Path]::GetExtension($scriptFile) -ine '.ps1'){throw 'Choose an existing reviewer .ps1 file.'}
    $path=[IO.Path]::ChangeExtension($scriptFile,'.cmd')
    # %~dpn0 binds this launcher to the adjacent same-name .ps1, including Unicode and punctuation.
    $text=@'
@echo off
setlocal DisableDelayedExpansion
set "MCR_SCRIPT=%~dpn0.ps1"
set "MCR_POWERSHELL=%SystemRoot%\System32\WindowsPowerShell\v1.0\powershell.exe"
if exist "%SystemRoot%\Sysnative\WindowsPowerShell\v1.0\powershell.exe" set "MCR_POWERSHELL=%SystemRoot%\Sysnative\WindowsPowerShell\v1.0\powershell.exe"
"%MCR_POWERSHELL%" -NoProfile -STA -Command "$ErrorActionPreference='Stop'; try { $p=$env:MCR_SCRIPT; if(-not [IO.File]::Exists($p)){throw ('Paired reviewer script is missing: '+$p)}; Unblock-File -LiteralPath $p; & $p; if(-not $?) {exit 1} } catch { Write-Error $_; exit 1 }"
set "MCR_EXIT=%ERRORLEVEL%"
if not "%MCR_EXIT%"=="0" pause
endlocal & exit /b %MCR_EXIT%
'@
    $text=$text.Replace("`r`n","`n").Replace("`n","`r`n")+"`r`n"
    if([IO.File]::Exists($path)){if([IO.File]::ReadAllText($path) -ceq $text){return $path};throw ('A different launcher already exists; it was preserved: '+$path)}
    $stream=[IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$bytes=[Text.Encoding]::ASCII.GetBytes($text);$stream.Write($bytes,0,$bytes.Length)}finally{$stream.Dispose()};return $path
}
function Invoke-ReviewerSupervisor([string]$ScriptPath,[Collections.IDictionary]$Parameters) {
    $root=Get-ReviewerRuntimeRoot;$directory=New-ReviewerRuntimeDirectory $root
    $lease=$null;$process=$null;$exitCode=1;$errorText=[Text.StringBuilder]::new();$started=$false;$reportedDiagnostic=$false;$marked=$false
    try{
        $lease=[IO.File]::Open((Join-Path $directory 'launcher.lease'),[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
        [IO.File]::WriteAllText((Join-Path $directory 'owner.marker'),'MediaComplianceReviewer-owned-v2');$marked=$true
        $hostPath=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe';if(-not [Environment]::Is64BitProcess){$hostPath=Join-Path $env:WINDIR 'Sysnative\WindowsPowerShell\v1.0\powershell.exe'}
        $arguments=[Collections.Generic.List[string]]::new();foreach($part in @('-NoProfile','-NonInteractive','-STA','-File',$ScriptPath,'-RuntimeInstance',$directory)){$arguments.Add($part)}
        foreach($key in $Parameters.Keys){if($key -in @('RuntimeInstance','CreateLauncher')){continue};$value=$Parameters[$key];if($value -is [Management.Automation.SwitchParameter]){if($value.IsPresent){$arguments.Add('-'+$key)}}else{$arguments.Add('-'+$key);$arguments.Add($(if($value -is [array]){$value -join ','}else{[string]$value}))}}
        $info=[Diagnostics.ProcessStartInfo]::new($hostPath,(($arguments | ForEach-Object {ConvertTo-ReviewerArgument $_}) -join ' '));$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
        $process=[Diagnostics.Process]::Start($info);$started=$true;$stdout=$process.StandardOutput.ReadLineAsync();$stderr=$process.StandardError.ReadLineAsync()
        # Best-effort abandoned cleanup runs in the supervisor, independently of WPF initialization.
        try{$examined=0;foreach($candidate in [IO.Directory]::EnumerateDirectories($root)){if(++$examined -gt 16){break};if($candidate -ine $directory){[void](Remove-ReviewerRuntime $root $candidate 100)}}}catch{Write-Warning ('Abandoned temporary cleanup was deferred: '+$_.Exception.Message)}
        while($stdout -or $stderr){
            if($stdout -and $stdout.IsCompleted){$line=$stdout.GetAwaiter().GetResult();if($null -eq $line){$stdout=$null}else{if($line.StartsWith('Startup diagnostic: ')){$reportedDiagnostic=$true};Write-Output $line;$stdout=$process.StandardOutput.ReadLineAsync()}}
            if($stderr -and $stderr.IsCompleted){$line=$stderr.GetAwaiter().GetResult();if($null -eq $line){$stderr=$null}else{if($errorText.Length -lt 8192){[void]$errorText.AppendLine($line.Substring(0,[Math]::Min($line.Length,8192-$errorText.Length)))};[Console]::Error.WriteLine($line);$stderr=$process.StandardError.ReadLineAsync()}}
            if($stdout -or $stderr){Start-Sleep -Milliseconds 20}
        }
        $process.WaitForExit();$exitCode=$process.ExitCode
        if($exitCode -ne 0 -and $errorText.Length -and -not $reportedDiagnostic){$saved=Save-ReviewerDiagnostic (Join-Path $directory 'startup.log') $errorText.ToString();if($saved){Write-Output ('Startup diagnostic: '+$saved)}}
    }finally{
        $finished=-not $started -or ($process -and $process.HasExited)
        if($process){$process.Dispose()};if($lease){$lease.Dispose()}
        if(-not $marked -and -not $started){try{[IO.File]::Delete((Join-Path $directory 'launcher.lease'));[IO.File]::Delete((Join-Path $directory 'owner.marker'));[IO.Directory]::Delete($directory,$false)}catch{Write-Warning ('Private startup cleanup could not finish: '+$directory)}}
        elseif($finished){
            $removed=Remove-ReviewerRuntime $root $directory
            foreach($delay in @(100,250,500)){if($removed){break};Start-Sleep -Milliseconds $delay;$removed=Remove-ReviewerRuntime $root $directory}
            if($removed){Write-Output 'Private temporary files removed.'}else{$notice='Some owned temporary files remain for cleanup on a later launch: '+$directory;Write-Warning $notice;[void](Save-ReviewerDiagnostic '' $notice)}
        }
    }
    if($exitCode -ne 0){throw ('The reviewer process exited with code '+$exitCode+'. Read the diagnostic above. Execution policy and application controls were not changed.')}
}

if($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage'){throw ('Application control has restricted PowerShell to '+$ExecutionContext.SessionState.LanguageMode+'. This application needs FullLanguage and permitted private assemblies. No policy change or bypass is attempted.')}
if($env:OS -ne 'Windows_NT'){throw 'This application requires 64-bit Windows.'}
if($CreateLauncher){
    if($PSBoundParameters.Count -ne 1){throw 'Use -CreateLauncher separately from other options.'}
    Write-Output ('Created launch helper: '+(New-ReviewerLauncher $PSCommandPath));return
}
# Dot-sourced dependency checks embed the runtime for development fixtures only.
$embeddedRuntime=$VerifyDependencies -and $MyInvocation.InvocationName -eq '.'
if(-not $RuntimeInstance -and -not $embeddedRuntime){Invoke-ReviewerSupervisor $PSCommandPath $PSBoundParameters;return}
if($OpenEvidencePackage -and ($VerifyDependencies -or $DatabasePath -or $ImportHtmlPath -or $ScanPath -or $ResumeScanId -or $CreateDatabase)){throw 'Open a protected package separately from database, scan, import or dependency-check options.'}
if($PSVersionTable.PSEdition -ne 'Desktop' -or -not [Environment]::Is64BitProcess){throw 'Use 64-bit Windows PowerShell 5.1 (powershell.exe), not PowerShell 7 or a 32-bit host.'}
if([Threading.Thread]::CurrentThread.GetApartmentState() -ne 'STA'){throw 'Start with powershell.exe -NoProfile -STA -File <script.ps1>.'}
if('MediaReviewer.Native' -as [type]){throw 'Start the portable script in a fresh PowerShell process to avoid mixing loaded dependency versions.'}
$applicationTempRoot=Get-ReviewerRuntimeRoot
$instanceDirectory=$RuntimeInstance
if($embeddedRuntime -and -not $RuntimeInstance){
    $instanceDirectory=New-ReviewerRuntimeDirectory $applicationTempRoot
    $instanceLease=[IO.FileStream]::new((Join-Path $instanceDirectory 'instance.lease'),[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
    [IO.File]::WriteAllText((Join-Path $instanceDirectory 'owner.marker'),'MediaComplianceReviewer-owned-v2')
}
if(-not (Test-ReviewerRuntimePath $applicationTempRoot $instanceDirectory)){throw 'The private runtime directory is invalid or is not owned by this application.'}
if(-not $embeddedRuntime){$instanceLease=[IO.FileStream]::new((Join-Path $instanceDirectory 'instance.lease'),[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}
$script:PortableReviewerPath=$PSCommandPath
$originalTemp=@{};foreach($name in @('TEMP','TMP','TMPDIR')){$originalTemp[$name]=[Environment]::GetEnvironmentVariable($name,'Process')}
$startupDiagnosticPath=Join-Path $instanceDirectory 'startup.log'
function Write-StartupDiagnostic([string]$Text){
    try{if($Text.Length -gt 8192){$Text=$Text.Substring(0,8192)};$entry=[Text.Encoding]::UTF8.GetBytes(([DateTime]::UtcNow.ToString('o')+' '+$Text+[Environment]::NewLine));$log=[IO.FileStream]::new($startupDiagnosticPath,[IO.FileMode]::Append,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$remaining=65536-$log.Length;if($remaining -gt 0){$log.Write($entry,0,[int][Math]::Min($entry.Length,$remaining))}}finally{$log.Dispose()}}catch{}
}
$splash=$null;$engine=$null
try {
    $workDirectory=Join-Path $instanceDirectory 'work';[IO.Directory]::CreateDirectory($workDirectory) | Out-Null
    foreach($name in @('TEMP','TMP','TMPDIR')){[Environment]::SetEnvironmentVariable($name,$workDirectory,'Process')}
    Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml
    Write-StartupDiagnostic ('PowerShell '+$PSVersionTable.PSVersion+'; language mode='+$ExecutionContext.SessionState.LanguageMode+'; apartment='+[Threading.Thread]::CurrentThread.GetApartmentState()+'; extracting verified startup helper')
    $assetManifestJson = @'
[{"Name":"MediaReviewer.Core.dll","Length":631808,"Sha256":"cd7d39664cf4623a5838c82580548ffa864970ffa2d753b5345e9e90ff016a3e"},{"Name":"MediaReviewer.Decoder.exe","Length":6144,"Sha256":"6fd4ee6986fa2c46bc7f77fe1fb707d0074170ee02e29b325fb215716074ce5e"},{"Name":"sqlite3.dll","Length":3518976,"Sha256":"5ca6a16bdd2c5a5037b1e3a942d9ac1c66efe2def902b202d44774680a8a4656"},{"Name":"libglib-2.0-0.dll","Length":1034752,"Sha256":"4069cb71b8e02b844e1dbac4200303fca81b8cbd5bb690a0dfa2059bca4816e6"},{"Name":"libgobject-2.0-0.dll","Length":216576,"Sha256":"c6c74e5f88ba692c009ddde1d7140120c4ede1b443259358481e0dd093b19af1"},{"Name":"libvips-42.dll","Length":17944064,"Sha256":"1b85669ea0de8ae2979863a4cacada0cd3089c01b9ec207b6b48ef6d3d0d71b5"},{"Name":"MainWindow.xaml","Length":12416,"Sha256":"3dc42fa0f9c36611bb62f8f3e8deeba499509d04e95b4a47ffff1263238ab04d"},{"Name":"THIRD-PARTY-NOTICES.txt","Length":158498,"Sha256":"f0a7484b71a49789bd0ebdbce658a538bfd8c3025e3074079b12ce63c8a57d30"},{"Name":"LicenseSections.json","Length":152020,"Sha256":"ef13835e342ba5f433660ba529d98b164fa10f2ac27e3c8d9abd88196e510248"},{"Name":"FFmpegSource-9.0.2.tar.xz","Length":12040788,"Sha256":"8c3850283eb25fa026482078a04051e0be17347b09ef81a0849bec15a96e002e"},{"Name":"FFmpegBuild.sh","Length":2578,"Sha256":"854a67de1766625264ddfc81727afd482ad1bfae43896f1e21970c95cdba5626"},{"Name":"avcodec-63.dll","Length":12826624,"Sha256":"36748481b0346737f79d37abb26a2307c30e56af7b659af3d8d90f68ab7f02a7"},{"Name":"avfilter-12.dll","Length":232448,"Sha256":"2362c196074bde290b6575fa90ba1b7021a5f8910416249121f67ef59d914baf"},{"Name":"avformat-63.dll","Length":1431040,"Sha256":"54412116b37c624c7c31ee21177c5fadae9fa35eb7baa7771d040f57ef04f3df"},{"Name":"avutil-61.dll","Length":727552,"Sha256":"06c92828b513e746a0c11be67c10a18b2856276c659862b1689fc6093ec742be"},{"Name":"ffmpeg.exe","Length":429056,"Sha256":"9859eaedfeb6a252a3325f8e756f46bd7b8aa06728e352b6047b25965443412c"},{"Name":"ffprobe.exe","Length":198144,"Sha256":"42ad83188288087473d4c173b6db72717c689855138d5c63d185517144e21e20"},{"Name":"swresample-7.dll","Length":114176,"Sha256":"8e5839b88ede4ac8392a763a2fc480bb2b1790ad1805b6a5af2b8e4135969d35"},{"Name":"swscale-10.dll","Length":1458176,"Sha256":"6dba7321a2a5a79684a87cbe1f6c860feb5310576bc6ad8461d211ac6381db3f"}]
'@
$assetManifest = $assetManifestJson | ConvertFrom-Json
    $helper=$assetManifest | Where-Object {$_.Name -eq 'MediaReviewer.Core.dll'}
    $helperCompressed=Join-Path $instanceDirectory 'bootstrap.gzip';$helperPath=Join-Path $instanceDirectory 'MediaReviewer.Core.dll'
    $reader=[IO.StreamReader]::new($PSCommandPath,[Text.Encoding]::UTF8,$true,65536)
    $compressed=[IO.File]::Create($helperCompressed)
    try {
        $found=$false;$ended=$false;$size=0L
        while(($line=$reader.ReadLine()) -ne $null){if($line -eq '#MCR-ASSET MediaReviewer.Core.dll'){$found=$true;break}}
        if(-not $found -or $helper.Length -gt 1MB){throw 'The embedded startup helper is missing or exceeds its size limit.'}
        while(($line=$reader.ReadLine()) -ne $null){if($line -eq '#MCR-END'){$ended=$true;break};if(-not $line.StartsWith('#') -or $line.Length -gt 32769){throw 'Malformed startup payload.'};$bytes=[Convert]::FromBase64String($line.Substring(1));$size+=$bytes.Length;if($size -gt 1MB){throw 'Startup payload exceeds its size limit.'};$compressed.Write($bytes,0,$bytes.Length)}
        if(-not $ended){throw 'Startup payload is truncated.'}
    } finally {$reader.Dispose();$compressed.Dispose()}
    $inputStream=[IO.File]::OpenRead($helperCompressed);$gzip=[IO.Compression.GZipStream]::new($inputStream,[IO.Compression.CompressionMode]::Decompress);$outputStream=[IO.File]::Create($helperPath)
    try {$block=[byte[]]::new(65536);$expanded=0L;while(($count=$gzip.Read($block,0,$block.Length)) -gt 0){$expanded+=$count;if($expanded -gt $helper.Length){throw 'Startup helper expanded beyond its declared length.'};$outputStream.Write($block,0,$count)}}finally{$outputStream.Dispose();$gzip.Dispose();$inputStream.Dispose()}
    if($expanded -ne $helper.Length -or (Get-FileHash -LiteralPath $helperPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne $helper.Sha256){throw 'Startup helper integrity check failed.'}
    Add-Type -Path $helperPath
    $preparation=[MediaReviewer.Distribution]::Prepare($PSCommandPath,$instanceDirectory,$assetManifestJson)
    $headless=$VerifyDependencies -or $ScanPath -or $ResumeScanId -or $ImportHtmlPath
    if(-not $headless){$splash=[Windows.Markup.XamlReader]::Parse('<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Starting Media Compliance Reviewer" Width="530" Height="180" ResizeMode="NoResize" WindowStartupLocation="CenterScreen" FontFamily="Segoe UI"><StackPanel Margin="24"><TextBlock Text="Starting Media Compliance Reviewer" FontSize="19" FontWeight="SemiBold"/><TextBlock x:Name="Stage" Text="Checking embedded dependencies…" Margin="0,16"/><ProgressBar Height="12" IsIndeterminate="True"/></StackPanel></Window>');$splash.Show()}
    while(-not $preparation.Done){if($splash){$splash.FindName('Stage').Text=$preparation.Stage;[Windows.Threading.Dispatcher]::CurrentDispatcher.Invoke([Action]{},[Windows.Threading.DispatcherPriority]::Background)};Start-Sleep -Milliseconds 25}
    if($preparation.Error){throw $preparation.Error}
    $script:EmbeddedMainWindowXaml=[IO.File]::ReadAllText((Join-Path $instanceDirectory 'MainWindow.xaml'),[Text.Encoding]::UTF8)
    $script:RuntimeLicenseText=[IO.File]::ReadAllText((Join-Path $instanceDirectory 'THIRD-PARTY-NOTICES.txt'),[Text.Encoding]::UTF8)
    $script:RuntimeLicenseSections=[IO.File]::ReadAllText((Join-Path $instanceDirectory 'LicenseSections.json'),[Text.Encoding]::UTF8) | ConvertFrom-Json
    function Get-UiReviewBucketLabel([string]$Bucket) { switch($Bucket){'TO_REVIEW'{'To be reviewed'};'COMPLIANT'{'Compliant'};'NON_COMPLIANT'{'Non-compliant'};'EVIDENCE'{'Evidence'}} }
function New-UiInspectionActions($Window,$Card) {
    $markup=@'
<StackPanel xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="0,0,0,8">
 <WrapPanel><Button x:Name="Compliant" Content="Compliant" Padding="12,6" Margin="0,0,6,5"/><Button x:Name="NonCompliant" Content="Non-compliant" Padding="12,6" Margin="0,0,6,5"/><Button x:Name="Unreviewed" Content="To be reviewed" Padding="12,6" Margin="0,0,6,5"/><Button x:Name="Evidence" Content="Evidence" Padding="12,6" Margin="0,0,6,5"/><Button x:Name="Reload" Content="Reload review" Padding="10,6" Margin="0,0,8,5" ToolTip="Reload the saved review revision; your draft stays visible"/><TextBlock x:Name="Bucket" VerticalAlignment="Center" Margin="0,0,0,5"/></WrapPanel>
 <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="150"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Text="Reviewer" VerticalAlignment="Center" Margin="0,0,6,0"/><TextBox Grid.Column="1" x:Name="Reviewer" MaxLength="128" Padding="4" VerticalContentAlignment="Center" AutomationProperties.Name="Inspection reviewer"/><TextBlock Grid.Column="2" Text="Notes" VerticalAlignment="Center" Margin="10,0,6,0"/><TextBox Grid.Column="3" x:Name="Notes" MaxLength="16384" Height="36" TextWrapping="Wrap" AcceptsReturn="True" VerticalScrollBarVisibility="Auto" Padding="4" AutomationProperties.Name="Inspection notes"/></Grid>
 <TextBlock x:Name="ReviewStatus" Height="60" TextWrapping="Wrap" Margin="0,5,0,0" AutomationProperties.Name="Inspection review status"/>
</StackPanel>
'@
    $panel=[Windows.Markup.XamlReader]::Parse($markup);$controls=@{};foreach($name in @('Compliant','NonCompliant','Unreviewed','Evidence','Reload','Bucket','Reviewer','Notes','ReviewStatus')){$controls[$name]=$panel.FindName($name)}
    $ctx=[pscustomobject]@{Window=$Window;Engine=$script:reviewUi.Engine;Card=$Card;Group=$Card.Record.GroupId;Content=$Card.Record.ContentId;Revision=$Card.Record.ReviewRevision;Bucket=$Card.Record.Status;Pending=$false;CanReview=$false;RefreshRequest='';Controls=$controls;InitialLoad=$true;Initializing=$false;ReviewerDirty=$false;NotesDirty=$false;TextReadOnly=$false}
    $Window | Add-Member -NotePropertyName ReviewContext -NotePropertyValue $ctx -Force
    $controls.Reviewer.Text=if($Card.Record.Reviewer){$Card.Record.Reviewer}else{$script:reviewUi.Controls.ReviewerBox.Text};$controls.Notes.Text=if($Card.Record.Notes){$Card.Record.Notes}else{$script:reviewUi.Controls.NotesBox.Text}
    $controls.Reviewer.Tag=$ctx;$controls.Notes.Tag=$ctx
    $controls.Reviewer.Add_TextChanged({param($sender,$event) if(-not $sender.Tag.Initializing){$sender.Tag.ReviewerDirty=$true}})
    $controls.Notes.Add_TextChanged({param($sender,$event) if(-not $sender.Tag.Initializing){$sender.Tag.NotesDirty=$true}})
    foreach($entry in @{Compliant='COMPLIANT';NonCompliant='NON_COMPLIANT';Unreviewed='TO_REVIEW';Evidence='EVIDENCE'}.GetEnumerator()){$button=$controls[$entry.Key];$button.Tag=[pscustomobject]@{Context=$ctx;Target=$entry.Value};$button.Add_Click({param($sender,$event) Invoke-UiInspectionReview $sender.Tag.Context $sender.Tag.Target})}
    $controls.Reload.Tag=$ctx;$controls.Reload.Add_Click({param($sender,$event) Refresh-UiInspectionReview $sender.Tag})
    Refresh-UiInspectionReview $ctx;Update-UiInspectionActions;return $panel
}
function Update-UiInspectionActions {
    $u=$script:reviewUi;if(-not $u){return}
    foreach($window in @($u.Inspector,$u.StoredWindow)){
        if(-not $window -or -not $window.ReviewContext){continue};$c=$window.ReviewContext
        $ready=[Object]::ReferenceEquals($c.Engine,$u.Engine) -and $u.Engine -and $u.Engine.Ready -and -not $u.Opening -and -not $u.Closing -and -not $u.ShutdownRequested -and -not $u.Preferences.Exit -and -not $u.Engine.ReportActive
        $pendingForItem=@($u.Pending.Values | Where-Object {$_.Ids -contains $c.Group}).Count -gt 0
        $available=$ready -and $c.CanReview -and -not $c.TextReadOnly -and -not $c.Pending -and -not $c.RefreshRequest -and -not $c.Card.IsPending -and -not $pendingForItem
        if($c.Bucket -eq 'EVIDENCE'){$available=$available -and -not $u.MaintenancePending -and $u.Engine.VaultUnlocked}
        $c.Controls.Compliant.IsEnabled=$available;$c.Controls.Unreviewed.IsEnabled=$available
        $c.Controls.NonCompliant.IsEnabled=$available -and -not $u.MaintenancePending;$c.Controls.Evidence.IsEnabled=$available -and -not $u.MaintenancePending -and $c.Bucket -ne 'EVIDENCE'
        $c.Controls.Reload.IsEnabled=$ready -and -not $c.Pending -and -not $c.RefreshRequest -and -not $c.Card.IsPending -and -not $pendingForItem
        $c.Controls.Reviewer.IsEnabled=-not $c.Pending;$c.Controls.Notes.IsEnabled=-not $c.Pending;$c.Controls.Bucket.Text='Bucket: '+(Get-UiReviewBucketLabel $c.Bucket)
    }
}
function Set-UiInspectionFeedback($Context,[string]$Text,[switch]$Complete) {
    if(-not $Context){return};if($Complete){$Context.Pending=$false;$Context.Card.IsPending=$false}
    if([Object]::ReferenceEquals($Context.Window.ReviewContext,$Context) -and [Object]::ReferenceEquals($Context.Engine,$script:reviewUi.Engine)){$Context.Controls.ReviewStatus.Text=$Text;$Context.Controls.ReviewStatus.ToolTip=$Text}
}
function Invoke-UiInspectionReview($Context,[string]$Status) {
    if(-not $Context -or -not [Object]::ReferenceEquals($Context.Window.ReviewContext,$Context)){return}
    Update-UiInspectionActions;$button=switch($Status){'COMPLIANT'{'Compliant'};'NON_COMPLIANT'{'NonCompliant'};'TO_REVIEW'{'Unreviewed'};'EVIDENCE'{'Evidence'};default{return}}
    if(-not $Context.Controls[$button].IsEnabled){return};$Context.Pending=$true;Set-UiInspectionFeedback $Context 'Saving review; preparing the requested action...';Update-UiInspectionActions
    Invoke-UiReview $Status @($Context.Card) $Context
}
function Refresh-UiInspectionReview($Context,[switch]$KeepFeedback) {
    if(-not $Context -or -not [Object]::ReferenceEquals($Context.Window.ReviewContext,$Context) -or -not [Object]::ReferenceEquals($Context.Engine,$script:reviewUi.Engine) -or $Context.Pending){return}
    try{$Context.CanReview=$false;$Context.RefreshRequest=$Context.Engine.RequestInspector($Context.Group,0);if(-not $KeepFeedback){Set-UiInspectionFeedback $Context 'Loading the current saved review; your draft is retained.'}}catch{Set-UiInspectionFeedback $Context ('Review reload failed: '+$_.Exception.Message)};Update-UiInspectionActions
}
function Apply-UiInspectionReviewResult($Result) {
    if($Result.Kind -ne 'Inspector'){return $false};$u=$script:reviewUi
    foreach($w in @($u.Inspector,$u.StoredWindow)){
        if(-not $w -or -not $w.ReviewContext -or $w.ReviewContext.RefreshRequest -ne $Result.RequestId){continue};$c=$w.ReviewContext;$c.RefreshRequest=''
        if(-not [Object]::ReferenceEquals($c.Engine,$u.Engine)){return $true}
        if(-not $Result.Success){Set-UiInspectionFeedback $c ('Review reload failed; draft retained: '+$Result.Error);Update-UiInspectionActions;return $true}
        $d=$Result.Inspector;if($d.GroupId -ne $c.Group){return $true};$c.Content=$d.ContentId;$c.Revision=$d.ReviewRevision;$c.Bucket=$d.Status;$c.Card.Record.ContentId=$d.ContentId;$c.Card.Record.ReviewRevision=$d.ReviewRevision;$c.Card.Record.Status=$d.Status;$c.CanReview=$true
        if($c.InitialLoad){$c.Initializing=$true;try{if(-not $c.ReviewerDirty){$c.Controls.Reviewer.Text=if($d.Reviewer){$d.Reviewer}else{$u.Controls.ReviewerBox.Text}};if(-not $c.NotesDirty){$c.Controls.Notes.Text=if($d.Notes){$d.Notes}elseif($d.Status -eq 'TO_REVIEW'){$u.Controls.NotesBox.Text}else{''}}}finally{$c.Initializing=$false}}
        $c.InitialLoad=$false;$c.TextReadOnly=$d.TextReadOnly;$c.Controls.Reviewer.IsReadOnly=$d.TextReadOnly;$c.Controls.Notes.IsReadOnly=$d.TextReadOnly
        if($d.TextReadOnly){Set-UiInspectionFeedback $c 'Extended or unsupported saved review text is read-only. Details / notes preserves its complete contents; review actions here cannot replace it with a shortened copy.';Update-UiInspectionActions;return $true}
        if($c.Controls.ReviewStatus.Text -notmatch '^(Committed|Review failed)'){Set-UiInspectionFeedback $c 'Current saved review loaded. Your draft is retained.'};Update-UiInspectionActions;return $true
    };return $false
}
function Clear-UiInspectionActions($Window) {if($Window.ReviewContext){$c=$Window.ReviewContext;$c.Controls.Reviewer.Clear();$c.Controls.Notes.Clear();$c.Controls.ReviewStatus.Text='';$Window.ReviewContext=$null}}

$script:uiSourceDirectory=$PSScriptRoot
function Set-UiMessage([string]$Text) { $script:reviewUi.Message=$Text; $script:reviewUi.Controls.MessageText.Text=$Text }
function Get-UiScanExtensions {
    $types=[Collections.Generic.List[string]]::new()
    foreach($family in [MediaReviewer.Formats]::Families){if($script:reviewUi.FormatChoices[$family.Key].IsChecked){$types.AddRange([string[]]$family.Extensions)}}
    return $types.ToArray()
}
function Update-UiFormatSummary {
    $types=@(Get-UiScanExtensions);$script:reviewUi.Controls.FormatsButton.Content=('File types ({0})…' -f $types.Count);$script:reviewUi.Controls.FormatsButton.ToolTip=($types -join ', ')
}
function Set-UiFormatPreset {
    $u=$script:reviewUi
    if($u.Controls.ModeBox.SelectedIndex -ne 2){$preset=if($u.Controls.ModeBox.SelectedIndex -eq 1){[MediaReviewer.Formats]::Deep}else{[MediaReviewer.Formats]::Quick};foreach($family in [MediaReviewer.Formats]::Families){$u.FormatChoices[$family.Key].IsChecked=$family.Extensions[0] -in $preset}}
    if($u.Controls.AppDataOption -and $u.Controls.ModeBox.SelectedIndex -ne 2){$u.Controls.AppDataOption.IsChecked=$u.Controls.ModeBox.SelectedIndex -eq 1}
    Update-UiFormatSummary
}
function Update-UiControls {
    $u=$script:reviewUi; if(-not $u){return}
    $ready=$u.Engine -and $u.Engine.Ready -and -not $u.Opening -and -not $u.Closing
    $ready=$ready -and -not $u.Preferences.Exit -and -not $u.ShutdownRequested;$running=$ready -and $u.Engine.Status.RunningScan
    foreach($name in @('CreateButton','OpenButton')){$u.Controls[$name].IsEnabled=-not $u.Opening -and -not $u.Closing -and -not $u.ShutdownRequested -and -not $running -and -not $u.MaintenancePending -and -not $u.Preferences.Exit}
    foreach($name in @('StartButton','BrowseButton','SourceBox','ModeBox','FormatsButton','JpegBox','PngBox','WorkerBox','AgeBox','OptionsButton','AppDataOption','RootFilesOption','ZipOption')){$u.Controls[$name].IsEnabled=$ready -and -not $running -and -not $u.MaintenancePending}
    $u.Controls.ResumeButton.IsEnabled=$ready -and -not $running -and [bool]$u.Engine.Status.ResumeId -and -not $u.Engine.ReportActive
    $u.Controls.CancelButton.IsEnabled=$ready -and $running -and -not $u.Engine.Status.CancelRequested
    $u.Controls.MaintenanceButton.IsEnabled=$ready -and -not $u.MaintenancePending
    $u.Controls.LogButton.IsEnabled=$ready
    $selected=@($u.Cards | Where-Object {$_.IsSelected}); $available=@($selected | Where-Object {-not $_.IsPending})
    $u.Controls.SelectionLabel.Text=('{0} selected' -f $selected.Count)
    foreach($name in @('CompliantButton','NonCompliantButton','UnreviewedButton')){$u.Controls[$name].IsEnabled=$ready -and $available.Count -gt 0 -and -not $u.Engine.ReportActive -and ($u.Bucket -ne 'EVIDENCE' -or -not $u.MaintenancePending)}
    $u.Controls.VerifyButton.IsEnabled=$ready -and -not $u.MaintenancePending -and $available.Count -eq 1 -and $available[0].Record.Algorithm -ne 'sha256' -and $u.Bucket -ne 'EVIDENCE'
    $u.Controls.IdentityHistoryButton.IsEnabled=$ready -and -not $u.MaintenancePending -and $available.Count -eq 1
    $u.Controls.CancelWorkButton.Visibility=if($u.MaintenancePending -or ($u.Opening -and $u.Engine) -or ($u.Preferences.Exit -and $u.Preferences.Exit.Kind -eq 'Open')){'Visible'}else{'Collapsed'}
    $u.Controls.CancelWorkButton.Content=if($u.Opening -or ($u.Preferences.Exit -and $u.Preferences.Exit.Kind -eq 'Open')){'Cancel opening'}else{'Cancel task'}
    $u.Controls.CancelWorkButton.IsEnabled=-not $u.CancelOpening
    foreach($name in @('SearchBox','FolderBox','TypeBox','SortBox','FitBox','FilterButton','ResetButton','PageSizeBox','PageBox','GoButton','ReviewerBox','NotesBox','CardList')){$u.Controls[$name].IsEnabled=$ready}
    Update-UiPreviewRecoveryControls;Update-UiSourceControls;Update-UiDetailsControls;Update-UiReportControls;Update-UiInspectionActions
    $u.Controls.ClearSelectionButton.IsEnabled=$selected.Count -gt 0
    # A refresh leaves committed cards visible and usable; it must not disable selection.
    $u.Controls.SelectPageButton.IsEnabled=$ready -and @($u.Cards | Where-Object {-not $_.IsPending}).Count -gt 0
    if($u.Controls.RetainOriginalsButton){$u.Controls.RetainOriginalsButton.IsEnabled=$ready -and -not $u.MaintenancePending -and @($available | Where-Object {$_.Record.Status -eq 'NON_COMPLIANT' -and -not $_.Record.OriginalRetained}).Count -gt 0}
    $u.Controls.PreviousButton.IsEnabled=$ready -and $u.Page -gt 1 -and -not $u.PagePending
    $u.Controls.NextButton.IsEnabled=$ready -and $u.Page -lt [Math]::Max(1,[Math]::Ceiling($u.Total/[double]$u.PageSize)) -and -not $u.PagePending
    if($u.Controls.VaultButton){$u.Controls.VaultButton.IsEnabled=$ready;$u.Controls.VaultButton.Content=if($ready -and $u.Engine.VaultUnlocked){'Lock originals'}else{'Unlock originals'};$u.Controls.CaptureEvidenceButton.IsEnabled=$ready -and -not $u.MaintenancePending -and $available.Count -gt 0 -and $u.Bucket -ne 'EVIDENCE';$u.Controls.StoredOriginalButton.IsEnabled=$ready -and $selected.Count -eq 1;$u.Controls.ExportOriginalButton.IsEnabled=$ready -and -not $u.MaintenancePending -and $available.Count -eq 1;$u.Controls.NonCompliantButton.IsEnabled=$u.Controls.NonCompliantButton.IsEnabled -and -not $u.MaintenancePending}
}
function New-UiRequest {
    $u=$script:reviewUi; $request=[MediaReviewer.PageRequest]::new()
    $request.Generation=$u.View.Current; $request.Bucket=$u.Bucket; $request.Page=$u.Page; $request.PageSize=$u.PageSize
    $request.Search=$u.Controls.SearchBox.Text; $request.Folder=$u.Controls.FolderBox.Text
    $request.Type=[string]$u.Controls.TypeBox.SelectedItem.Tag; $request.Sort=[string]$u.Controls.SortBox.SelectedItem.Tag
    return $request
}
function Request-UiPage([switch]$Reset,[switch]$Refill) {
    $u=$script:reviewUi; if(-not $u.Engine -or -not $u.Engine.Ready -or $u.Closing){return}
    if($Reset){[void]$u.View.Advance();$u.Cards.Clear();$u.PagePending=$false}
    $request=New-UiRequest
    if($Refill -and $u.Cards.Count){$request.ExistingIds=[long[]]@($u.Cards | ForEach-Object {$_.Record.GroupId})}
    try {$u.PageRequest=$u.Engine.RequestPage($request);$u.PagePending=$true;Set-UiMessage 'Loading results…'} catch {Set-UiMessage ('Results request failed: '+$_.Exception.Message);$u.PagePending=$false}
    Update-UiControls
}
function Add-UiCard($Record) {
    $card=[MediaReviewer.CardItem]::new($Record)
    $card.add_PropertyChanged({param($sender,$event) if($event.PropertyName -eq 'IsSelected'){$script:reviewUi.SelectionGeneration++};if($event.PropertyName -in @('IsSelected','IsPending') -and -not ($script:reviewUi.GallerySelection -and $script:reviewUi.GallerySelection.Updating)){Update-UiControls}})
    $script:reviewUi.Cards.Add($card)
}
function Apply-UiResult($Result) {
    if($Result.Kind -in @('Preferences','PreferencesSaved')){return (Apply-UiPreferencesResult $Result)}
    if($Result.Kind -in @('SourceCheck','SourceApply','SourceDiscard','SourceRoots','SourceConnectionStatus')){return (Apply-UiSourceResult $Result)}
    $u=$script:reviewUi
    if($Result.Kind -in @('PreviewRetry','PreviewRetryHistory','PreviewRetryStatus')){return (Apply-UiPreviewRecoveryResult $Result)}
    if($Result.Kind -in @('Inspector','Locations','Notes')){if(Apply-UiInspectionReviewResult $Result){return $Result.Success};return (Apply-UiDetailsResult $Result)}
    if($Result.Kind -eq 'Page') {
        if(-not $u.View.Accept($Result.Generation) -or $Result.RequestId -ne $u.PageRequest){return $false}
        $u.PagePending=$false
        if(-not $Result.Success){Set-UiMessage ('Page load failed: '+$Result.Error);return $false}
        if(-not $Result.Page.Refill){$u.SourceRefreshRequired=$false};$data=$Result.Page; $u.Page=$data.Page; $u.PageSize=$data.PageSize;$u.Total=$data.Total;$u.LastRevision=$data.Revision
        if($data.Refill){foreach($row in $data.Rows){if(-not @($u.Cards | Where-Object {$_.Record.GroupId -eq $row.GroupId}).Count){Add-UiCard $row}}}
        else {
            $existing=@{};foreach($card in $u.Cards){$existing[$card.Record.GroupId]=$card}
            $wanted=[Collections.Generic.HashSet[long]]::new();foreach($row in $data.Rows){[void]$wanted.Add($row.GroupId)}
            for($i=$u.Cards.Count-1;$i -ge 0;$i--){if(-not $wanted.Contains($u.Cards[$i].Record.GroupId)){$u.Cards.RemoveAt($i)}}
            $position=0;foreach($row in $data.Rows){if($existing.ContainsKey($row.GroupId)){$card=$existing[$row.GroupId];$card.Update($row);$current=$u.Cards.IndexOf($card);if($current -ne $position){$u.Cards.Move($current,$position)}}else{Add-UiCard $row;$u.Cards.Move($u.Cards.Count-1,$position)};$position++}
        }
        $labels=@('To be reviewed','Compliant','Non-compliant','Evidence');$tabs=@('ToReviewTab','CompliantTab','NonCompliantTab','EvidenceTab')
        for($i=0;$i -lt 4;$i++){$u.Controls[$tabs[$i]].Content=('{0} ({1:n0})' -f $labels[$i],$data.Totals[$i])}
        $u.Controls.PageBox.Text=[string]$u.Page;$u.Controls.PageLabel.Text=('Page {0:n0} of {1:n0} · {2:n0} matching items · {3} shown' -f $u.Page,[Math]::Max(1,[Math]::Ceiling($u.Total/[double]$u.PageSize)),$u.Total,$u.Cards.Count)
        $u.Controls.EmptyPanel.Visibility=if($u.Cards.Count){[Windows.Visibility]::Collapsed}else{[Windows.Visibility]::Visible}
        $u.Controls.EmptyTitle.Text=if($u.Bucket -eq 'EVIDENCE'){'Evidence is locked'}else{'No matching media'}
        $u.Controls.EmptyText.Text=if($u.Bucket -eq 'EVIDENCE'){'Protected originals use placeholder cards. Clear filters, select a card, and use Stored original to unlock and authenticate it.'}else{'Choose another bucket or Reset view. You can scan while reviewing.'}
        Update-UiDetailsControls;if($u.Inspector){Update-UiItemNavigation $u.Inspector $u.InspectGroup 'PreviousItem' 'NextItem' 'Position';Resume-UiInspectorSource}
        Set-UiMessage 'Results loaded.';Update-UiControls;return $true
    }
    if($Result.Kind -in @('Review','OriginalRetention')) {
        if(-not $u.Pending.ContainsKey($Result.RequestId)){return $false}
        $operation=$u.Pending[$Result.RequestId];$u.Pending.Remove($Result.RequestId)
        if($Result.RequestId -eq $u.BackgroundOperationId){$u.MaintenancePending=$false;$u.BackgroundOperationId=''}
        foreach($card in $u.Cards){if($operation.Ids -contains $card.Record.GroupId){$card.IsPending=$false}}
        if(-not $Result.Success){if($operation.Capture){$u.RetentionRetry=[pscustomobject]@{Database=$u.Engine.DatabasePath;Request=$operation.Request;PreserveReview=[bool]$operation.PreserveReview}};Set-UiInspectionFeedback $operation.Context ('Review failed; item and draft retained: '+$Result.Error) -Complete;if($operation.Capture -and $operation.Context){Refresh-UiInspectionReview $operation.Context -KeepFeedback};Set-UiMessage ($(if($Result.Kind -eq 'OriginalRetention'){'Retention failed; selection retained: '}else{'Review failed; selection retained: '})+$Result.Error);Update-UiControls;return $false}
        if($operation.Capture){$u.RetentionRetry=$null}
        Set-UiInspectionFeedback $operation.Context ('Committed · '+(Get-UiReviewBucketLabel $operation.Target)) -Complete
        if($operation.Context){Refresh-UiInspectionReview $operation.Context -KeepFeedback}
        if($operation.Target -eq 'EVIDENCE' -and $u.Inspector -and $operation.Ids -contains $u.InspectGroup){$u.Inspector.Close()}
        if($u.Bucket -eq $operation.Bucket -and $u.Bucket -ne $operation.Target){for($i=$u.Cards.Count-1;$i -ge 0;$i--){if($operation.Ids -contains $u.Cards[$i].Record.GroupId){$u.Cards.RemoveAt($i)}}}
        else{foreach($card in $u.Cards){if($operation.Ids -contains $card.Record.GroupId){$card.IsSelected=$false}}}
        [void]$u.View.Advance();$u.LastRevision=$u.Engine.Status.Revision
        Set-UiMessage ('Committed · '+$u.Engine.Status.LastCommitUtc.ToLocalTime().ToString('HH:mm:ss'))
        if($u.Bucket -eq $operation.Bucket -and $u.Bucket -ne $operation.Target){Request-UiPage -Refill}else{Request-UiPage}
        Update-UiControls;return $true
    }
    if($Result.Kind -eq 'Log') {
        if($u.LogWindow -and $Result.RequestId -eq $u.LogRequest){$u.LogText.Text=if($Result.Success){$Result.Value}else{'Log read failed: '+$Result.Error}}
        return $Result.Success
    }
    if(Apply-UiEvidenceResult $Result){return $Result.Success}
    if($Result.Kind -in @('FullVerification','IdentityResolution','IdentityHistory')){
        if(-not $u.IdentityTask -or $Result.RequestId -ne $u.IdentityTask.RequestId){return $false}
        $task=$u.IdentityTask;$u.IdentityTask=$null;$u.MaintenancePending=$false;$u.BackgroundOperationId=''
        foreach($card in $u.Cards){if($card.Record.GroupId -eq $task.GroupId){$card.IsPending=$false}}
        if(-not $Result.Success){Set-UiMessage ($Result.Kind+' failed; selection retained: '+$Result.Error);if($u.IdentityWindow){$u.IdentityWindow.FindName('Status').Text=$Result.Error;$u.IdentityWindow.FindName('Apply').IsEnabled=$true};Update-UiControls;return $false}
        if($Result.Kind -eq 'FullVerification'){
            $u.IdentityPreview=$Result.IdentityPreview
            if($task.View -eq $u.View.Current -and $task.Selection -eq $u.SelectionGeneration -and $Result.IdentityPreview.Revision -eq $u.Engine.Status.Revision){Show-UiIdentityPreview $Result.IdentityPreview}else{Set-UiMessage 'Verification finished. Select its card and click Verify full to review the result.'}
        }elseif($Result.Kind -eq 'IdentityHistory'){
            if($task.View -eq $u.View.Current -and $task.Selection -eq $u.SelectionGeneration){if($u.IdentityHistoryWindow){$u.IdentityHistoryWindow.Close()};$u.IdentityHistoryWindow=New-TextWindow 'Identity history' $Result.Value;$u.IdentityHistoryWindow.Add_Closed({$script:reviewUi.IdentityHistoryWindow=$null});$u.IdentityHistoryWindow.Show();Set-UiMessage 'Identity history ready.'}else{Set-UiMessage 'History read finished; selection changed.'}
        }else{
            if($u.IdentityWindow){$u.IdentityWindow.Close()};$u.IdentityPreview=$null
            Invalidate-UiDetailsGroup $task.GroupId;if($u.Inspector -and $u.InspectGroup -eq $task.GroupId){$u.Inspector.Close()};[void]$u.View.Advance();$u.LastRevision=$u.Engine.Status.Revision
            Request-UiPage;Set-UiMessage $Result.Value
        };Update-UiControls;return $true
    }
    if($Result.Kind -in @('Backup','Integrity','Import','Export','Report','EvidencePackageExport')){if($u.BackgroundOperationId -and $Result.RequestId -ne $u.BackgroundOperationId){return $false};$u.MaintenancePending=$false;$u.BackgroundOperationId='';Set-UiMessage $(if($Result.Success){$Result.Value}else{$Result.Kind+': '+$Result.Error});Update-UiControls;return $Result.Success}
    return $false
}
function Invoke-UiReview([string]$Status,$Cards=$null,$Context=$null) {
    $u=$script:reviewUi;$cards=if($Context){@($Cards | Where-Object {-not $_.IsPending})}else{@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending})};if(-not $cards.Count){Set-UiInspectionFeedback $Context 'This item already has a pending action.' -Complete;return}
    $request=[MediaReviewer.ReviewRequest]::new();$request.OperationId=[Guid]::NewGuid().ToString('N');$request.GroupIds=[long[]]@($cards | ForEach-Object {$_.Record.GroupId});$request.Status=$Status;$request.Reviewer=$u.Controls.ReviewerBox.Text;$request.Notes=$u.Controls.NotesBox.Text
    $bucket=$u.Bucket;if($Context){$bucket=$Context.Bucket;$request.Reviewer=$Context.Controls.Reviewer.Text;$request.Notes=$Context.Controls.Notes.Text;$request.ExpectedRevisions=[Collections.Generic.Dictionary[long,long]]::new();$request.ExpectedRevisions[$Context.Group]=$Context.Revision}
    if($Status -in @('NON_COMPLIANT','EVIDENCE') -or $bucket -eq 'EVIDENCE'){Start-UiOriginalRetention $request $bucket $false $Context;return}
    Set-UiMessage ('Saving '+$cards.Count+' selected item(s)…')
    try{$requestId=$u.Engine.RequestReview($request);$u.Pending[$requestId]=[pscustomobject]@{Ids=$request.GroupIds;Bucket=$bucket;Target=$Status;OperationId=$request.OperationId;Context=$Context};foreach($card in $cards){$card.IsPending=$true}}
    catch{Set-UiInspectionFeedback $Context ('Review failed; item and draft retained: '+$_.Exception.Message) -Complete;Set-UiMessage ('Review failed; selection retained: '+$_.Exception.Message)}
    Update-UiControls
}
function New-TextWindow([string]$Title,[string]$Text) {
    $markup='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Width="820" Height="590" MinWidth="500" MinHeight="350" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBox x:Name="Body" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="10"/><StackPanel Grid.Row="1" Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,12,0,0"><Button x:Name="Save" Content="Save text…" Padding="14,6" Margin="6"/><Button x:Name="Close" Content="Close" Padding="20,6" Margin="6"/></StackPanel></Grid></Window>'
    $dialog=[Windows.Markup.XamlReader]::Parse($markup);$dialog.Title=$Title;$dialog.Owner=$script:reviewUi.Window;$dialog.FindName('Body').Text=$Text
    $dialog.FindName('Close').Add_Click({param($sender,$event) $sourceWindow=[Windows.Window]::GetWindow($sender);$sourceWindow.Close()})
    $dialog.FindName('Save').Add_Click({param($sender,$event) $sourceWindow=[Windows.Window]::GetWindow($sender);$picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Filter='Text file (*.txt)|*.txt';$picker.FileName='Media-Reviewer-log.txt';if($picker.ShowDialog($sourceWindow)){[IO.File]::WriteAllText($picker.FileName,$sourceWindow.FindName('Body').Text,[Text.UTF8Encoding]::new($false))}})
    return $dialog
}
function Show-UiShutdown([string]$Stage,[bool]$Failed=$false) {
    $u=$script:reviewUi;$u.Controls.ShutdownPanel.Visibility='Visible';$u.Controls.ShutdownTitle.Text=if($Failed){'Preferences could not be saved'}else{'Closing safely'}
    $u.Controls.ShutdownStage.Text=$Stage;$u.Controls.ShutdownStage.ToolTip=$Stage;$u.Controls.ShutdownProgress.IsIndeterminate=-not $Failed
    foreach($name in @('ShutdownRetryButton','ShutdownKeepSavedButton')){$u.Controls[$name].Visibility=if($Failed){'Visible'}else{'Collapsed'}}
    $u.Controls.ActivityText.Text=$Stage;$u.Window.Title='Media Compliance Reviewer — closing';[void]$u.Controls.ShutdownPanel.Focus()
}
function Start-UiShutdown {
    $u=$script:reviewUi;if($u.Closing){return};$u.ShutdownRequested=$true;$u.Closing=$true;$u.NextOpen=$null;$u.Preferences.Exit=$null
    Show-UiShutdown 'Stopping background work and closing the database. Please wait for confirmation.'
    if($script:packageWindow){$u.ClosingPackage=$script:packageWindow;$u.ClosingPackage.Close()}
    foreach($name in @('ReportWindow','RecoveryWindow','SourcesWindow','Inspector','IdentityWindow','IdentityHistoryWindow','LogWindow')){if($u.$name){$u.$name.Close()}}
    Clear-UiStoredView;$u.Loader.CloseAsync();if($u.Engine){$u.Engine.CloseAsync()};Update-UiControls
}
function Update-UiShutdownWaiting {
    $u=$script:reviewUi;if(-not $u.ShutdownRequested -or $u.Closing){return}
    if($u.Preferences.ErrorSignature -and -not $u.Preferences.SaveRequest){Show-UiShutdown ('The last preference change was not confirmed saved. Retry, or close using the previously saved preferences. '+$u.Controls.PreferencesText.Text) $true}
    else{Show-UiShutdown 'Saving preferences; waiting for the commit before closing the database.'}
}
function Invoke-UiShutdownTick {
    $u=$script:reviewUi
    if($u.ClosingPackage){if(-not $u.ClosingPackage.Tag.Session.Closed){Show-UiShutdown 'Closing protected package; waiting for its owned work to stop.';return};Invoke-PackageTick $u.ClosingPackage;$u.ClosingPackage=$null}
    if($u.Engine -and -not $u.Engine.Closed){Show-UiShutdown $(if($u.Engine.CloseStage){$u.Engine.CloseStage}else{'Closing database workers...'});return}
    if(-not $u.Loader.Closed){Show-UiShutdown 'Database connections closed; waiting for preview workers to stop.';return}
    if(-not $u.ShutdownCompletedAt){
        $u.ShutdownCompletedAt=[DateTime]::UtcNow;$u.Controls.ShutdownProgress.IsIndeterminate=$false
        $u.Controls.ShutdownTitle.Text=if($u.Engine -and $u.Engine.Faulted){'Database connections closed'}elseif($u.Engine){'Database closed'}else{'Application closed'}
        $u.Controls.ShutdownStage.Text=if($u.Engine -and $u.Engine.Faulted){'Earlier committed work is retained. The database reported: '+$u.Engine.Status.Error}else{'Background work has stopped. Exiting...'}
        $u.Controls.ActivityText.Text=$u.Controls.ShutdownTitle.Text;return
    }
    # Keep the completed state visible briefly without blocking the Dispatcher.
    if(([DateTime]::UtcNow-$u.ShutdownCompletedAt).TotalSeconds -ge 1){$u.AllowClose=$true;if($u.Timer){$u.Timer.Stop()};$u.Window.Close()}
}
function Invoke-UiIdentity([switch]$History) {
    $u=$script:reviewUi;$cards=@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending});if($cards.Count -ne 1 -or $u.MaintenancePending){return};$card=$cards[0]
    if(-not $History -and $u.IdentityPreview -and $u.IdentityPreview.Remaining -eq 0 -and $u.IdentityPreview.GroupId -eq $card.Record.GroupId -and $u.IdentityPreview.Revision -eq $u.Engine.Status.Revision){Show-UiIdentityPreview $u.IdentityPreview;return}
    try{
        $id=if($History){$u.Engine.RequestIdentityHistory($card.Record.GroupId)}else{$u.Engine.RequestFullVerification($card.Record.GroupId,$null)}
        $u.IdentityTask=[pscustomobject]@{RequestId=$id;GroupId=$card.Record.GroupId;View=$u.View.Current;Selection=$u.SelectionGeneration};$u.MaintenancePending=$true;$u.BackgroundOperationId=$id;$card.IsPending=$true
        Set-UiMessage $(if($History){'Reading identity history…'}else{'Verifying full contents of current source locations…'});Update-UiControls
    }catch{Set-UiMessage ('Verification request failed; selection retained: '+$_.Exception.Message)}
}
function Apply-UiMediaResult($Image) {
    $u=$script:reviewUi
    if($Image.Kind -eq 'Thumbnail' -and $u.MediaView.Accept($Image.Generation)){$card=$u.Cards | Where-Object {$_.Record.GroupId -eq $Image.GroupId} | Select-Object -First 1;if($card -and $card.Record.ContentId -eq $Image.ContentId -and $card.Record.PreviewRevision -eq $Image.PreviewRevision){$card.SetImage($Image.Image,$Image.Error);Update-UiInspectorThumbnail $card;return $true}}
    if($Image.Kind -eq 'Inspect'){return (Apply-UiInspectorImage $Image)}
    return $false
}
function Show-UiIdentityPreview([MediaReviewer.IdentityResolutionPreview]$Preview) {
    $u=$script:reviewUi;if($u.IdentityWindow){$u.IdentityWindow.Close()}
    $markup='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Review full verification" Width="780" Height="610" MinWidth="520" MinHeight="420" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/><RowDefinition Height="58"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock x:Name="Summary" TextWrapping="Wrap" Margin="0,0,0,10"/><TextBox Grid.Row="1" x:Name="Body" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Padding="8"/><CheckBox Grid.Row="2" x:Name="Accept" Content="Keep the existing verified decisions and preserve the candidate review in history" Margin="0,10"/><TextBlock Grid.Row="3" x:Name="Status" TextWrapping="Wrap"/><StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Center"><Button x:Name="Apply" Content="Apply verified identities" Padding="14,7" Margin="6"/><Button x:Name="Close" Content="Close" Padding="24,7" Margin="6"/></StackPanel></Grid></Window>'
    $dialog=[Windows.Markup.XamlReader]::Parse($markup);$dialog.Owner=$u.Window;$dialog.Tag=[pscustomobject]@{Preview=$Preview;OperationId=[Guid]::NewGuid().ToString('N')};$u.IdentityWindow=$dialog
    $dialog.FindName('Summary').Text=('Group {0} · {1} locations · {2} distinct full identities. {3}' -f $Preview.GroupId,$Preview.Locations,$Preview.Outcomes.Count,$Preview.Message)
    $lines=[Collections.Generic.List[string]]::new();$lines.Add(('Candidate review: {0}; reviewer: {1}; notes (first 2048 characters): {2}' -f $Preview.SourceStatus,$Preview.SourceReviewer,$Preview.SourceNotes))
    foreach($outcome in $Preview.Outcomes){$destination=if($outcome.ExistingGroupId){'Existing group '+$outcome.ExistingGroupId}elseif($outcome.Anchor){'Original card; decision retained'}else{'New card; To be reviewed'};$lines.Add("`r`n$destination`r`nSHA-256: $($outcome.Hash)`r`nExample location (first 512 characters): $($outcome.ExamplePath)`r`nLocations: $($outcome.Locations) · Decision: $($outcome.Status)`r`nReviewer: $($outcome.Reviewer)`r`nNotes (first 512 characters): $($outcome.Notes)")};$dialog.FindName('Body').Text=$lines -join "`r`n"
    $dialog.FindName('Accept').Visibility=if($Preview.HasConflicts){'Visible'}else{'Collapsed'};$dialog.FindName('Apply').IsEnabled=$Preview.CanApply -and -not $Preview.HasConflicts
    $dialog.FindName('Accept').Add_Click({param($sender,$event) $window=[Windows.Window]::GetWindow($sender);$window.FindName('Apply').IsEnabled=$window.Tag.Preview.CanApply -and [bool]$sender.IsChecked})
    $dialog.FindName('Apply').Add_Click({param($sender,$event)
        $u=$script:reviewUi;$window=[Windows.Window]::GetWindow($sender);if($u.MaintenancePending){return};$preview=$window.Tag.Preview;$preview.AcceptConflicts=[bool]$window.FindName('Accept').IsChecked
        try{$id=$u.Engine.RequestIdentityResolution($preview,$window.Tag.OperationId);$u.IdentityTask=[pscustomobject]@{RequestId=$id;GroupId=$preview.GroupId;View=$u.View.Current;Selection=$u.SelectionGeneration};$u.MaintenancePending=$true;$u.BackgroundOperationId=$id;$sender.IsEnabled=$false;$window.FindName('Accept').IsEnabled=$false;$window.FindName('Status').Text='Preparing bounded batches; the visible identity changes only after publication commits.';foreach($card in $u.Cards){if($card.Record.GroupId -eq $preview.GroupId){$card.IsPending=$true}};Set-UiMessage 'Applying verified identities…';Update-UiControls}catch{$window.FindName('Status').Text=$_.Exception.Message}
    })
    $dialog.FindName('Close').Add_Click({param($sender,$event) [Windows.Window]::GetWindow($sender).Close()});$dialog.Add_Closed({$script:reviewUi.IdentityWindow=$null})
    $dialog.Show();Set-UiMessage 'Full verification is ready for review; changes have not been applied.'
}
function New-AboutWindow {
    $markup='<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="About and licenses" Width="820" Height="620" MinWidth="500" MinHeight="360" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI"><Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock x:Name="Credits" TextWrapping="Wrap" Margin="0,0,0,12" FontSize="14"/><ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto"><StackPanel x:Name="LicenseSections"/></ScrollViewer><Button Grid.Row="2" x:Name="Close" Content="Close" IsCancel="True" HorizontalAlignment="Center" Padding="24,7" Margin="0,12,0,0"/></Grid></Window>'
    $dialog=[Windows.Markup.XamlReader]::Parse($markup);if($script:reviewUi.Window.IsLoaded){$dialog.Owner=$script:reviewUi.Window}
    $dialog.FindName('Credits').Text="Media Compliance Reviewer for Windows`r`nMade by $([MediaReviewer.Product]::Author)`r`nDate: $([MediaReviewer.Product]::RevisionDate)    Version: $([MediaReviewer.Product]::Version)`r`nPortable offline Windows PowerShell 5.1 / .NET Framework / WPF"
    $sections=$script:RuntimeLicenseSections
    if(-not $sections){$sections=[IO.File]::ReadAllText((Join-Path ([MediaReviewer.Native]::RuntimeDirectory) 'LicenseSections.json'),[Text.Encoding]::UTF8) | ConvertFrom-Json}
    foreach($section in $sections){
        $expander=[Windows.Controls.Expander]::new();$expander.Header=[string]$section.Title;$expander.Margin='0,4,0,4';$expander.Padding='6'
        $body=[Windows.Controls.TextBox]::new();$body.IsReadOnly=$true;$body.TextWrapping='Wrap';$body.VerticalScrollBarVisibility='Auto';$body.MaxHeight=320;$body.Padding='8';$body.Text=[string]$section.Text
        $expander.Content=$body;$dialog.FindName('LicenseSections').Children.Add($expander) | Out-Null
    }
    if($script:PortableReviewerPath -and (Get-Command New-ReviewerLauncher -ErrorAction SilentlyContinue)){
        $launchSection=[Windows.Controls.Expander]::new();$launchSection.Header='Launch helper';$launchSection.Margin='0,4,0,4';$launchSection.Padding='6'
        $launchPanel=[Windows.Controls.StackPanel]::new();$launchText=[Windows.Controls.TextBlock]::new();$launchText.TextWrapping='Wrap';$launchText.Text='Create an optional .cmd beside this script. It removes the Internet mark from only its paired .ps1 and starts 64-bit Windows PowerShell 5.1. Keep both files together with matching names. Execution policy stays unchanged.';$launchPanel.Children.Add($launchText) | Out-Null
        $launchButton=[Windows.Controls.Button]::new();$launchButton.Content='Create launch helper';$launchButton.HorizontalAlignment='Left';$launchButton.Margin='0,8,0,0';$launchButton.Padding='12,6';$launchButton.Tag=$script:PortableReviewerPath
        $launchButton.Add_Click({param($sender,$event) try{$path=New-ReviewerLauncher ([string]$sender.Tag);[Windows.MessageBox]::Show([Windows.Window]::GetWindow($sender),('Launch helper: '+$path),'Launch helper created',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Information) | Out-Null}catch{[Windows.MessageBox]::Show([Windows.Window]::GetWindow($sender),$_.Exception.Message,'Launch helper unavailable',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Error) | Out-Null}})
        $launchPanel.Children.Add($launchButton) | Out-Null;$launchSection.Content=$launchPanel;$dialog.FindName('LicenseSections').Children.Add($launchSection) | Out-Null
    }
    $dialog.FindName('Close').Add_Click({param($sender,$event) [Windows.Window]::GetWindow($sender).Close()})
    return $dialog
}
function Get-UiNativeDestination([string]$Source) {
    $picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Title='HTML database detected — choose a new local Windows copy; the original is preserved'
    $picker.Filter='Native SQLite database|*.sqlite';$picker.FileName=[IO.Path]::GetFileNameWithoutExtension($Source)+'-Windows.sqlite';$picker.OverwritePrompt=$false
    if($picker.ShowDialog($script:reviewUi.Window)){return $picker.FileName}
    return $null
}
function Open-UiDatabase([string]$Path,[bool]$Create,[string]$ImportSource='') {
    if(-not $Create -and -not $ImportSource -and [IO.Path]::GetExtension($Path) -ieq '.mcrevidence'){Show-UiPackage $Path;return}
    if($script:packageWindow){$script:packageWindow.Close()}
    if($script:reviewUi.DetailsWindow){$script:reviewUi.DetailsWindow.Close();if($script:reviewUi.DetailsWindow){return}}
    if($script:reviewUi.ReportWindow){$script:reviewUi.ReportWindow.Close()};if($script:reviewUi.LimitsWindow){$script:reviewUi.LimitsWindow.Close()};Clear-UiStoredView;[void]$script:reviewUi.InspectView.Advance();$script:reviewUi.InspectGroup=0
    if($script:reviewUi.Inspector){$script:reviewUi.Inspector.Close();$script:reviewUi.Inspector=$null}
    if(-not (Test-UiPreferencesExit ([pscustomobject]@{Kind='Open';Path=$Path;Create=$Create;ImportSource=$ImportSource}))){Update-UiControls;return};Initialize-UiPreferences
    if($script:reviewUi.RecoveryWindow){$script:reviewUi.RecoveryWindow.Close()};if($script:reviewUi.SourcesWindow){$script:reviewUi.SourcesWindow.Close()}
    $u=$script:reviewUi;$u.Opening=$true;$u.CancelOpening=$false;$u.SourceRefreshRequired=$false;$u.Cards.Clear();[void]$u.View.Advance();[void]$u.MediaView.Advance();$u.Pending.Clear();$u.Initialized=$false;$u.PagePending=$false;$u.PageRequest='';$u.BackgroundOperationId='';$u.MaintenancePending=$false
    if($u.IdentityWindow){$u.IdentityWindow.Close()};if($u.IdentityHistoryWindow){$u.IdentityHistoryWindow.Close()};$u.IdentityTask=$null;$u.IdentityPreview=$null
    $u.Controls.EmptyPanel.Visibility=[Windows.Visibility]::Visible;$u.Controls.EmptyTitle.Text=if($Create){'Creating database'}else{'Opening database'};$u.Controls.EmptyText.Text='Database controls stay unavailable until initialization succeeds.'
    $u.NextOpen=[pscustomobject]@{Path=$Path;Create=$Create;ImportSource=$ImportSource}
    if($u.Engine){$u.Engine.CloseAsync()}else{$u.HtmlPrompted=$false;$u.Engine=if($ImportSource){[MediaReviewer.ReviewerEngine]::ImportHtml($ImportSource,$Path)}else{[MediaReviewer.ReviewerEngine]::Open($Path,$Create)};$u.NextOpen=$null}
    Update-UiControls
}
function Invoke-UiTick {
    $u=$script:reviewUi;if(-not $u){return}
    try {
        if($u.Closing){
            Invoke-UiShutdownTick;return
        }
        if($u.CancelOpening){
            if(-not $u.Engine -or $u.Engine.Closed){
                $u.Engine=$null;$u.NextOpen=$null;$u.CancelOpening=$false;$u.Opening=$false;$u.Initialized=$false;$u.PagePending=$false
                $u.Controls.DatabaseLabel.Text='No database open';$u.Controls.ActivityText.Text='Ready'
                $u.Controls.EmptyPanel.Visibility=[Windows.Visibility]::Visible;$u.Controls.EmptyTitle.Text='Opening cancelled';$u.Controls.EmptyText.Text='Choose Create or Open to continue.'
                Set-UiMessage 'Initialization cancelled; original files and completed commits were retained.'
            }else{$u.Controls.ActivityText.Text='Cancelling initialization; waiting for owned workers.'}
            Update-UiControls;return
        }
        if($u.NextOpen){
            if($u.Engine -and -not $u.Engine.Closed){$u.Controls.ActivityText.Text='Closing the previous database; waiting for owned workers.';Update-UiControls;return}
            $next=$u.NextOpen;$u.NextOpen=$null;$u.HtmlPrompted=$false;$u.Engine=if($next.ImportSource){[MediaReviewer.ReviewerEngine]::ImportHtml($next.ImportSource,$next.Path)}else{[MediaReviewer.ReviewerEngine]::Open($next.Path,$next.Create)}
        }
        if($u.Engine){
            $status=$u.Engine.Status
            if($u.Engine.DetectedHtml -and -not $u.HtmlPrompted){
                $u.HtmlPrompted=$true;$source=$u.Engine.DatabasePath;$destination=Get-UiNativeDestination $source
                if($destination){Open-UiDatabase -Path $destination -Create $true -ImportSource $source}else{$u.CancelOpening=$true;$u.NextOpen=$null;$u.Engine.CloseAsync();Set-UiMessage 'Conversion cancelled; the original database was retained.'}
                return
            }
            if(-not $u.Initialized -and $u.Engine.Ready -and -not $u.Preferences.LoadRequest -and -not $u.Preferences.LoadFailed){try{$u.Preferences.LoadRequest=$u.Engine.RequestPreferences();$u.Controls.PreferencesText.Text='Loading saved preferences...'}catch{$u.Preferences.LoadFailed=$true;$u.Controls.PreferencesText.Text=$_.Exception.Message;$u.Controls.RetryPreferencesButton.Visibility='Visible'}}
            if($u.Engine.Faulted){$u.Opening=$false;$u.Controls.EmptyPanel.Visibility=[Windows.Visibility]::Visible;$u.Controls.EmptyTitle.Text='Database unavailable';$u.Controls.EmptyText.Text=$status.Error;Set-UiMessage ('Database stopped: '+$status.Error)}
            $stage=$status.Stage;if($u.BackgroundOperationId){$background=$u.Engine.GetOperationProgress($u.BackgroundOperationId);if($background){$stage=$background.Stage}}
            $u.Controls.ActivityText.Text=('{0} · user {1}/{2} · {3:n0}/{4:n0} files processed · {5:n0} errors · {6:n0} queued · WAL {7:n1} MiB' -f $stage,$status.CompletedUsers,$status.TotalUsers,$status.ProcessedFiles,$status.DiscoveredFiles,$status.FailedFiles,$status.PendingWork,($status.WalBytes/1MB))
            [MediaReviewer.UiResult]$reply=$null;$drained=0
            while($drained -lt 8 -and $u.Engine.TryTakeResult([ref]$reply)){Apply-UiResult $reply | Out-Null;$drained++}
            Invoke-UiPreferencesTick;Complete-UiPreferencesExit
            Update-UiShutdownWaiting
            Invoke-UiStoredIntent
            if($u.Initialized -and -not $u.Opening -and -not $u.PagePending -and $status.Revision -ne $u.LastRevision -and ([DateTime]::UtcNow-$u.LastRefresh).TotalSeconds -ge 1 -and -not $u.Pending.Count){$u.LastRefresh=[DateTime]::UtcNow;Request-UiPage}
        }
        [MediaReviewer.MediaLoadResult]$image=$null;$drained=0
        while($drained -lt 8 -and $u.Loader.TryTakeResult([ref]$image)){
            Apply-UiMediaResult $image | Out-Null
            $drained++
        }
        $queued=0
        foreach($card in $u.Cards){if($queued -ge 20){break};if($card.CanLoadImage){if($u.Loader.QueueThumbnail($card.Record.GroupId,$card.Record.ContentId,$u.MediaView.Current,$card.Record.PreviewBytes,$card.Record.PreviewRevision)){$card.ImageQueued=$true;$card.Record.PreviewBytes=$null;$queued++}else{break}}}
        Update-UiControls
    } catch{Set-UiMessage ('Interface operation failed: '+$_.Exception.Message)}
}
function New-ReviewerWindow([MediaReviewer.ReviewerEngine]$Engine=$null) {
    Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml,System.Windows.Forms
    $markup=if($script:EmbeddedMainWindowXaml){$script:EmbeddedMainWindowXaml}else{[IO.File]::ReadAllText((Join-Path $script:uiSourceDirectory 'MainWindow.xaml'),[Text.Encoding]::UTF8)}
    $window=[Windows.Markup.XamlReader]::Parse($markup);$controls=@{}
    foreach($name in @('DatabaseLabel','CreateButton','OpenButton','MaintenanceButton','LogButton','HelpButton','AboutButton','SourceBox','BrowseButton','StartButton','ResumeButton','CancelButton','ModeBox','FormatsButton','JpegBox','PngBox','WorkerBox','AgeBox','OptionsButton','SelectPageButton','ToReviewTab','CompliantTab','NonCompliantTab','EvidenceTab','SearchBox','FolderBox','TypeBox','SortBox','FitBox','FilterButton','ResetButton','ActionBar','SelectionLabel','ReviewerBox','NotesBox','CompliantButton','NonCompliantButton','UnreviewedButton','ClearSelectionButton','GalleryScroll','CardList','EmptyPanel','EmptyTitle','EmptyText','PageSizeBox','PreviousButton','NextButton','PageBox','GoButton','PageLabel','StatusPanel','ActivityText','MessageText')){$controls[$name]=$window.FindName($name)}
    $script:reviewUi=[pscustomobject]@{Window=$window;Controls=$controls;Engine=$Engine;Loader=[MediaReviewer.MediaLoader]::new();Cards=[Collections.ObjectModel.ObservableCollection[MediaReviewer.CardItem]]::new();View=[MediaReviewer.ViewGeneration]::new();MediaView=[MediaReviewer.ViewGeneration]::new();InspectView=[MediaReviewer.ViewGeneration]::new();InspectGroup=0L;Inspector=$null;Page=1;PageSize=60;Bucket='TO_REVIEW';Total=0L;LastRevision=-1L;LastRefresh=[DateTime]::UtcNow;PagePending=$false;PageRequest='';Pending=@{};Message='';Opening=[bool]$Engine;Initialized=$false;NextOpen=$null;Closing=$false;AllowClose=$false;Timer=$null;LogWindow=$null;LogText=$null;LogRequest='';MaintenancePending=$false;SuppressEvents=$false}
    $script:reviewUi | Add-Member -NotePropertyName DetailsWindow -NotePropertyValue $null
    $script:reviewUi | Add-Member -NotePropertyName ClosingPackage -NotePropertyValue $null
    $script:reviewUi | Add-Member -NotePropertyName ShutdownRequested -NotePropertyValue $false
    $script:reviewUi | Add-Member -NotePropertyName ShutdownCompletedAt -NotePropertyValue $null
    foreach($name in @('ShutdownPanel','ShutdownTitle','ShutdownStage','ShutdownProgress','ShutdownRetryButton','ShutdownKeepSavedButton')){$controls[$name]=$window.FindName($name)}
    $controls.ShutdownRetryButton.Add_Click({$u=$script:reviewUi;$u.Preferences.ErrorSignature='';$u.Preferences.Exit=[pscustomobject]@{Kind='Close'};Show-UiShutdown 'Retrying the preference save before closing...';Invoke-UiPreferencesTick -Flush})
    $controls.ShutdownKeepSavedButton.Add_Click({Start-UiShutdown})
    $script:reviewUi | Add-Member -NotePropertyName DetailsGeneration -NotePropertyValue ([MediaReviewer.ViewGeneration]::new())
    $controls.CardList.ItemsSource=$script:reviewUi.Cards
    $script:reviewUi | Add-Member -NotePropertyName GallerySelection -NotePropertyValue ([MediaReviewer.GallerySelection]::new($controls.GalleryScroll,$controls.CardList,$script:reviewUi.Cards))
    $script:reviewUi.GallerySelection.add_Changed({Update-UiControls})
    $window.Add_Closed({$script:reviewUi.GallerySelection.Dispose()})
    foreach($name in @('VerifyButton','IdentityHistoryButton')){$controls[$name]=$window.FindName($name)}
    foreach($name in @('IdentityTask','IdentityPreview','IdentityWindow','IdentityHistoryWindow')){$script:reviewUi | Add-Member -NotePropertyName $name -NotePropertyValue $null}
    $script:reviewUi | Add-Member -NotePropertyName SelectionGeneration -NotePropertyValue 0L
    $controls.VerifyButton.Add_Click({Invoke-UiIdentity});$controls.IdentityHistoryButton.Add_Click({Invoke-UiIdentity -History})
    $controls['CancelWorkButton']=$window.FindName('CancelWorkButton')
    $script:reviewUi | Add-Member -NotePropertyName BackgroundOperationId -NotePropertyValue ''
    $script:reviewUi | Add-Member -NotePropertyName CancelOpening -NotePropertyValue $false
    $script:reviewUi | Add-Member -NotePropertyName HtmlPrompted -NotePropertyValue $false
    $controls.CancelWorkButton.Add_Click({$u=$script:reviewUi;if($u.Opening -or ($u.Preferences.Exit -and $u.Preferences.Exit.Kind -eq 'Open')){$u.Preferences.Exit=$null;$u.Opening=$true;$u.CancelOpening=$true;$u.NextOpen=$null;if($u.Engine){$u.Engine.CloseAsync()};Set-UiMessage 'Cancelling initialization; waiting for owned work to stop…';Update-UiControls}elseif($u.BackgroundOperationId){$u.Engine.CancelOperation($u.BackgroundOperationId);Set-UiMessage 'Cancellation requested; waiting for the current bounded operation…'}})
    $script:reviewUi | Add-Member -NotePropertyName FormatChoices -NotePropertyValue @{}
    $controls['FormatsButton']=$window.FindName('FormatsButton');$formatMenu=[Windows.Controls.ContextMenu]::new()
    foreach($family in [MediaReviewer.Formats]::Families){
        $choice=[Windows.Controls.MenuItem]::new();$choice.Header=$family.Label;$choice.ToolTip=($family.Extensions -join ', ');$choice.IsCheckable=$true;$choice.StaysOpenOnClick=$true;$choice.IsChecked=$family.Extensions[0] -in [MediaReviewer.Formats]::Quick
        $choice.Add_Click({$script:reviewUi.Controls.ModeBox.SelectedIndex=2;Update-UiFormatSummary});$script:reviewUi.FormatChoices[$family.Key]=$choice;$formatMenu.Items.Add($choice) | Out-Null
