    $controls.BrowseButton.Add_Click({$picker=[Windows.Forms.FolderBrowserDialog]::new();$picker.Description='Choose the home-share root. Missing mapped drives? Run normally with the same Windows account as Explorer, or enter a UNC path in Source root.';try{if($picker.ShowDialog() -eq [Windows.Forms.DialogResult]::OK){$script:reviewUi.Controls.SourceBox.Text=$picker.SelectedPath}}finally{$picker.Dispose()}})
