    $controls.ModeBox.Add_SelectionChanged({Set-UiFormatPreset})
    $controls.HelpButton.Add_Click({$dialog=New-TextWindow 'Help' "Create or open a local SQLite database. Keep the active WAL database off network and synchronized shares. Media sources may be local, mapped drives, or UNC shares.`r`n`r`nEnter the source root whose immediate subfolders are user homes. Select types and exclusions, then Start scan. Open recognizes saved databases from the final HTML build (schema 4) and asks for a new local Windows copy. The original is preserved. Cancel opening stops initialization; Cancel task stops backup/integrity work. The saved alphabetical manifest is used for Resume; a fresh scan finds later additions to completed users. Reparse points are skipped.`r`n`r`nSelect cards, Shift-click a range, or drag a rectangle from the gallery background. Ctrl adds to a range or drag. Select page selects the visible page. Then click a review action. Saving means queued; Committed means the write succeeded. Inspector uses the saved preview immediately and requests a bounded source preview separately. Fit shows the whole image; Fill crops around the center. The inspector sizes source previews for the window and zoom, with bounded pixel memory. Use +/-, Ctrl+wheel, 100% and dragging/scrolling; source and preview dimensions identify sampling. The inspector offers Compliant, Non-compliant, To be reviewed and Evidence actions for its displayed item, independent of gallery selection. Its reviewer and notes fields retain drafts on failure; Reload review refreshes the saved revision. Previous/next follows the visible gallery page. Details / notes on each card shows saved metadata and locations in pages of up to 100. Save notes changes reviewer text without changing buckets. Extended imported text is read-only; failed saves retain the draft.`r`n`r`nA failed preview retains its fingerprinted record. Select cards and choose Retry previews to regenerate saved thumbnails or posters without changing reviews. Preview tasks shows outcomes and resumes interrupted work. Existing good previews survive failures. Schema 9 upgrades create a validated pre-upgrade backup for native schemas 1 through 8. Open Log for affected paths and retries. Ordinary records and thumbnails are not encrypted. Non-compliant and Evidence actions retain encrypted originals. For older Non-compliant decisions without originals, Retain originals preserves saved notes and reviewer labels while capturing verified encrypted originals; already retained items are skipped. Create or unlock the originals vault when prompted. Stored original authenticates saved bytes; Export original writes a new full-resolution file you explicitly choose. Lock originals clears protected views. Maintenance offers Retention limits with optional database and original-file caps; zero means no fixed cap. Free working space is always checked. It also offers bounded cleanup of unfinished captures.`r`n`r`nQuick selects common image and video types. Quick includes HEIC/HEIF and other common images. Deep adds RAW and includes AppData. Options controls AppData, root-level files and optional ZIP scanning. ZIP is off by default. Stored/Deflate ZIP and ZIP64 members use full SHA-256, bounded expansion and CRC checks. Changed archives need a fresh scan for pending members. See Log for rejected archives. File types edits a Custom selection. Videos use saved posters; RAW uses an embedded JPEG when available. Preview limits/failures do not discard fingerprints. Both scan modes use quick fingerprints above 1 MiB; small files and previously full-hashed paths receive full SHA-256. Candidate matches do not prove identical files. Select one candidate and use Verify full, then review and apply its full identities. Existing verified decisions require explicit conflict acknowledgement. Identity history retains archived reviews. Sources and the database must still match the prepared result. Collisions must be resolved before retaining originals. Ordinary metadata and thumbnails remain unencrypted. Select Evidence cards and choose a review bucket to authenticate and reclassify them. Maintenance offers Change originals password; earlier database copies retain their old password. Maintenance offers Sources / reconnect to check moved or copied media before applying a connection. Imported HTML folder-picker roots may have no Windows path; cancel scanning, check and apply their folder in Sources / reconnect, then retry the selected review. Maintenance offers Export review report for CSV and offline HTML pages. Reports are plaintext; explicitly included Evidence details require an unlocked originals vault and authentication. Maintenance exports selected encrypted originals as protected packages. Open .mcrevidence packages read only with the originals password; Export original writes plaintext only to your chosen new file. Full playback remains unavailable. ZIP previews may use bounded private temporary files; Evidence capture streams directly without plaintext staging.`r`n`r`nResume works after cancellation, window close or process interruption: reopen the same local database and choose Resume scan. Completed users are skipped; unfinished directory enumeration or file reads can repeat. New files in completed users need a fresh scan. Blank preference values are valid. If optional preferences cannot be read, labelled defaults allow opening while saved settings remain preserved for Retry preferences. SQLite recovers interrupted journal state on open; access denial, disk full, unsupported schemas or damaged pages are reported without replacing the original database.`r`n`r`nClose with X to stop owned work and close the database. Closing safely shows the current stage; Database closed confirms completion before exit. A failed preference save offers Retry preferences or Close with last saved preferences.";$dialog.ShowDialog() | Out-Null})
    $controls.AboutButton.Add_Click({$dialog=New-AboutWindow;$dialog.ShowDialog() | Out-Null})
    $controls.LogButton.Add_Click({try{$u=$script:reviewUi;if($u.LogWindow){$u.LogWindow.Activate() | Out-Null;return};$u.LogWindow=New-TextWindow 'Log' 'Loading recent scan summaries and retry details…';$u.LogText=$u.LogWindow.FindName('Body');$u.LogWindow.Add_Closed({$script:reviewUi.LogWindow=$null;$script:reviewUi.LogText=$null});$u.LogWindow.Show();$u.LogRequest=$u.Engine.RequestLog()}catch{Set-UiMessage $_.Exception.Message}})
    $menu=[Windows.Controls.ContextMenu]::new()
    $backupItem=[Windows.Controls.MenuItem]::new();$backupItem.Header='Portable backup…';$backupItem.Add_Click({try{$u=$script:reviewUi;$picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Filter='SQLite backup (*.sqlite)|*.sqlite';$picker.FileName='Media-Review-backup.sqlite';$picker.OverwritePrompt=$false;if($picker.ShowDialog($u.Window)){$u.BackgroundOperationId=$u.Engine.RequestBackup($picker.FileName);$u.MaintenancePending=$true;Set-UiMessage 'Backup queued…';Update-UiControls}}catch{Set-UiMessage ('Backup failed: '+$_.Exception.Message)}});$menu.Items.Add($backupItem) | Out-Null
    $checkItem=[Windows.Controls.MenuItem]::new();$checkItem.Header='Check database integrity';$checkItem.Add_Click({try{$u=$script:reviewUi;$u.BackgroundOperationId=$u.Engine.RequestIntegrity();$u.MaintenancePending=$true;Set-UiMessage 'Integrity check queued…';Update-UiControls}catch{Set-UiMessage $_.Exception.Message}});$menu.Items.Add($checkItem) | Out-Null
    $controls.MaintenanceButton.ContextMenu=$menu;$controls.MaintenanceButton.Add_Click({param($sender,$event) $sender.ContextMenu.PlacementTarget=$sender;$sender.ContextMenu.IsOpen=$true})
    $window.Add_Closing({
        param($sender,$event) $u=$script:reviewUi;if($u.AllowClose){return};$event.Cancel=$true;if($u.Closing){return}
        if($u.DetailsWindow){$u.DetailsWindow.Close();if($u.DetailsWindow){return}}
        $u.ShutdownRequested=$true
        if(-not (Test-UiPreferencesExit ([pscustomobject]@{Kind='Close'}))){Update-UiShutdownWaiting;Update-UiControls;return}
        Start-UiShutdown
    })
    Update-UiControls
    Add-UiPreferencesControls;Add-UiEvidenceControls $window
    Add-UiPreviewRecoveryControls $window;Add-UiReportControls;Add-UiPackageControls
    Update-UiControls
    return $window
}
function Start-ReviewerInterface {
    $window=New-ReviewerWindow
    $timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds(100);$timer.Add_Tick({Invoke-UiTick});$script:reviewUi.Timer=$timer;$timer.Start()
    $work=[Windows.SystemParameters]::WorkArea;$window.Width=[Math]::Min($window.Width,$work.Width);$window.Height=[Math]::Min($window.Height,$work.Height)
    [void]$window.ShowDialog()
    if($script:reviewUi.ShutdownCompletedAt){Write-Output ($script:reviewUi.Controls.ShutdownTitle.Text+'. Committed work is retained.')}
}

