function Initialize-UiPreferences {
    $u=$script:reviewUi
    $state=[pscustomobject]@{Loaded=$false;ReadOnly=$false;LoadFailed=$false;LoadRequest='';SaveRequest='';Saved='';Observed='';Current=$null;InFlight=$null;OperationId='';AttemptSignature='';Due=[DateTime]::UtcNow;ErrorSignature='';LastValidAge=0;Exit=$null}
    if($u.PSObject.Properties['Preferences']){$u.Preferences=$state}else{$u | Add-Member -NotePropertyName Preferences -NotePropertyValue $state}
}
function Get-UiPreferences {
    $u=$script:reviewUi;$p=[MediaReviewer.ReviewPreferences]::new()
    $p.PageSize=[int]$u.Controls.PageSizeBox.SelectedItem;$p.Fit=[string]$u.Controls.FitBox.SelectedItem.Tag;$p.WorkerCount=[int]$u.Controls.WorkerBox.SelectedItem
    $p.Mode=@('Quick','Deep','Custom')[$u.Controls.ModeBox.SelectedIndex];$p.Families=[string[]]@([MediaReviewer.Formats]::Families | Where-Object {$u.FormatChoices[$_.Key].IsChecked} | ForEach-Object {$_.Key})
    $age=0;if([int]::TryParse($u.Controls.AgeBox.Text,[ref]$age) -and $age -ge 0 -and $age -le 9999){$u.Preferences.LastValidAge=$age};$p.ModifiedAgeYears=$u.Preferences.LastValidAge
    $p.IncludeApplicationData=[bool]$u.Controls.AppDataOption.IsChecked;$p.IncludeRootFiles=[bool]$u.Controls.RootFilesOption.IsChecked;$p.ScanArchives=[bool]$u.Controls.ZipOption.IsChecked;$p.Reviewer=$u.Controls.ReviewerBox.Text
    return $p
}
function Restore-UiPreferences([MediaReviewer.ReviewPreferences]$Preferences) {
    $u=$script:reviewUi;$p=$Preferences;$u.SuppressEvents=$true
    try{
        $u.Controls.PageSizeBox.SelectedItem=$p.PageSize;$u.PageSize=$p.PageSize;$u.Controls.FitBox.SelectedIndex=if($p.Fit -eq 'UniformToFill'){1}else{0};$u.Controls.WorkerBox.SelectedItem=$p.WorkerCount
        $u.Controls.ModeBox.SelectedIndex=[Array]::IndexOf(@('Quick','Deep','Custom'),$p.Mode)
        foreach($family in [MediaReviewer.Formats]::Families){$u.FormatChoices[$family.Key].IsChecked=$family.Key -in $p.Families};Update-UiFormatSummary
        $u.Controls.AppDataOption.IsChecked=$p.IncludeApplicationData;$u.Controls.RootFilesOption.IsChecked=$p.IncludeRootFiles;$u.Controls.ZipOption.IsChecked=$p.ScanArchives;$u.Controls.AgeBox.Text=[string]$p.ModifiedAgeYears;$u.Preferences.LastValidAge=$p.ModifiedAgeYears;$u.Controls.ReviewerBox.Text=$p.Reviewer
        $u.Page=1;$u.Bucket='TO_REVIEW';$u.Controls.NotesBox.Clear();$u.Controls.SearchBox.Clear();$u.Controls.FolderBox.Clear();$u.Controls.TypeBox.SelectedIndex=0;$u.Controls.SortBox.SelectedIndex=0;$u.Controls.PageBox.Text='1'
    }finally{$u.SuppressEvents=$false}
    $s=$u.Preferences;$s.Loaded=$true;$s.LoadFailed=$false;$s.ReadOnly=$p.ReadOnly;$s.Current=Get-UiPreferences;$s.Saved=$s.Current.Signature;$s.Observed=$s.Saved
    $u.Controls.PreferencesText.Text=if($p.Warning){$p.Warning}else{'Preferences loaded for this database.'}
    $u.Controls.PreferencesText.ToolTip=$u.Controls.PreferencesText.Text
    $u.Controls.RetryPreferencesButton.Visibility='Hidden';$u.Initialized=$true;$u.Opening=$false;$u.Controls.DatabaseLabel.Text=$u.Engine.DatabasePath;Request-UiPage -Reset
}
function Invoke-UiPreferencesTick([switch]$Flush) {
    $u=$script:reviewUi;$s=$u.Preferences;if(-not $s -or -not $s.Loaded -or $s.ReadOnly -or -not $u.Engine -or -not $u.Engine.Ready -or $u.Closing -or $u.Opening){return}
    try{$current=Get-UiPreferences;$signature=$current.Signature}catch{$u.Controls.PreferencesText.Text='Preferences not saved: '+$_.Exception.Message;return}
    if($signature -cne $s.Observed){$s.Observed=$signature;$s.Current=$current;$s.Due=[DateTime]::UtcNow.AddMilliseconds(500);$s.ErrorSignature='';$u.Controls.RetryPreferencesButton.Visibility='Hidden';$u.Controls.PreferencesText.Text='Preferences pending...'}
    if($signature -ceq $s.Saved -and -not $s.SaveRequest){if($u.Controls.PreferencesText.Text -eq 'Preferences pending...'){$u.Controls.PreferencesText.Text='Preferences unchanged.'};return}
    if(-not $s.SaveRequest -and $s.ErrorSignature -cne $signature -and ($Flush -or [DateTime]::UtcNow -ge $s.Due)){
        if($s.AttemptSignature -cne $signature){$s.OperationId=[Guid]::NewGuid().ToString('N');$s.AttemptSignature=$signature}
        try{$s.SaveRequest=$u.Engine.RequestSavePreferences($s.Current,$s.OperationId);$s.InFlight=$signature;$u.Controls.PreferencesText.Text='Preferences saving...'}
        catch{$s.ErrorSignature=$signature;$s.Exit=$null;$u.Controls.PreferencesText.Text='Preferences not queued: '+$_.Exception.Message;$u.Controls.RetryPreferencesButton.Visibility='Visible'}
    }
}
function Test-UiPreferencesExit($Next) {
    $u=$script:reviewUi;$s=$u.Preferences
    if(-not $s.Loaded -or $s.ReadOnly -or -not $u.Engine.Ready -or $u.Engine.Faulted){return $true}
    Invoke-UiPreferencesTick -Flush
    if($s.SaveRequest -or $s.Observed -cne $s.Saved){if(-not $s.ErrorSignature){$s.Exit=$Next};return $false}
    return $true
}
function Complete-UiPreferencesExit {
    $u=$script:reviewUi;$s=$u.Preferences;if(-not $s.Exit){return};Invoke-UiPreferencesTick -Flush
    if($u.Engine.Faulted -or (-not $s.SaveRequest -and $s.Observed -ceq $s.Saved)){$next=$s.Exit;$s.Exit=$null;if($next.Kind -eq 'Close'){$u.Window.Close()}else{Open-UiDatabase $next.Path $next.Create $next.ImportSource}}
}
function Apply-UiPreferencesResult($Result) {
    $u=$script:reviewUi;$s=$u.Preferences
    if($Result.Kind -eq 'Preferences'){
        if(-not $s.LoadRequest -or $Result.RequestId -ne $s.LoadRequest){return $false};$s.LoadRequest=''
        $failure=$Result.Error
        if($Result.Success){try{Restore-UiPreferences $Result.Preferences;return $true}catch{$failure=$_.Exception.Message}}
        # Optional UI settings must not make an otherwise open database inaccessible.
        $defaults=[MediaReviewer.ReviewPreferences]::new();$defaults.ReadOnly=$true
        if($failure.Length -gt 1024){$failure=$failure.Substring(0,1024)}
        $defaults.Warning='Preferences unavailable; defaults are active. Saved preferences were preserved. Retry preferences to reload them. '+$failure
        Restore-UiPreferences $defaults;$s.LoadFailed=$true;$u.Controls.RetryPreferencesButton.Visibility='Visible';return $true
    }
    if($Result.Kind -eq 'PreferencesSaved'){
        if(-not $s.SaveRequest -or $Result.RequestId -ne $s.SaveRequest){return $false};$s.SaveRequest=''
        if($Result.Success){$s.Saved=$s.InFlight;$u.Controls.PreferencesText.Text=if($s.Saved -ceq $s.Observed){'Preferences committed.'}else{'Preferences pending...'}}
        else{$s.ErrorSignature=$s.InFlight;$s.Exit=$null;$u.Controls.PreferencesText.Text='Preferences not saved: '+$Result.Error;$u.Controls.RetryPreferencesButton.Visibility='Visible'};return $true
    };return $false
}
function Add-UiPreferencesControls {
    $u=$script:reviewUi;foreach($name in @('PreferencesText','RetryPreferencesButton')){$u.Controls[$name]=$u.Window.FindName($name)};Initialize-UiPreferences
    $u.Controls.RetryPreferencesButton.Add_Click({$u=$script:reviewUi;$s=$u.Preferences;if(-not $s.Loaded -or $s.LoadFailed){try{$s.LoadRequest=$u.Engine.RequestPreferences();$u.Controls.PreferencesText.Text='Loading saved preferences...';$u.Controls.RetryPreferencesButton.Visibility='Hidden'}catch{$u.Controls.PreferencesText.Text=$_.Exception.Message}}else{$s.ErrorSignature='';Invoke-UiPreferencesTick -Flush}})
}

function Update-UiReportControls {
    $u=$script:reviewUi;$w=$u.ReportWindow;if(-not $w){return};$ready=$u.Engine -and $u.Engine.Ready -and -not $u.Opening -and -not $u.Closing -and -not $u.MaintenancePending -and -not $u.Engine.Status.RunningScan -and -not $u.Pending.Count -and -not ($u.DetailsWindow -and $u.DetailsWindow.Tag.Saving)
    $w.FindName('Export').IsEnabled=$ready;$w.FindName('Unlock').IsEnabled=$ready -and -not $u.Engine.VaultUnlocked;$w.FindName('Unlock').Content=if($u.Engine.VaultUnlocked){'Originals unlocked'}else{'Unlock originals...'}
}
function Start-UiReport {
    $u=$script:reviewUi;$w=$u.ReportWindow;if(-not $w -or $u.MaintenancePending){return}
    try{if($u.Pending.Count -or ($u.DetailsWindow -and $u.DetailsWindow.Tag.Saving)){throw 'Wait for the pending review to commit before exporting.'};$options=[MediaReviewer.ReportOptions]::new();$options.Destination=$w.FindName('Destination').Text;$options.Format=if($w.FindName('Format').SelectedIndex -eq 1){'HtmlDirectory'}else{'Csv'};$options.IncludeEvidence=[bool]$w.FindName('IncludeEvidence').IsChecked;$options.IncludeSavedPreviews=[bool]$w.FindName('Previews').IsChecked;$options.SpreadsheetSafeText=[bool]$w.FindName('SafeText').IsChecked
        $u.BackgroundOperationId=$u.Engine.RequestReport($options);$u.MaintenancePending=$true;Set-UiMessage 'Report queued. Review changes are paused; cached inspection remains available. Use Cancel task to stop.';$w.Close();Update-UiControls
    }catch{$w.FindName('Status').Text=$_.Exception.Message;Update-UiReportControls}
}
function Show-UiReport {
    $u=$script:reviewUi;if(-not $u.Engine -or -not $u.Engine.Ready -or $u.Opening -or $u.MaintenancePending){return}
    if(-not $u.ReportWindow){$markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Export review report" Width="680" Height="590" MinWidth="580" MinHeight="540" WindowStartupLocation="CenterOwner" FontFamily="Segoe UI" FontSize="14">
  <Grid Margin="20"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
    <TextBlock Text="Export all Non-compliant items and their recorded locations. Reports use saved data without reading source folders. Finish or cancel scanning first. Review changes pause while export runs; cached inspection stays available." TextWrapping="Wrap" Margin="0,0,0,14"/>
    <WrapPanel Grid.Row="1" Margin="0,0,0,12"><TextBlock Text="Format" VerticalAlignment="Center" Margin="0,0,10,0"/><ComboBox x:Name="Format" Width="270" SelectedIndex="0" MinHeight="32"><ComboBoxItem Content="CSV file"/><ComboBoxItem Content="Offline HTML folder + complete CSV"/></ComboBox></WrapPanel>
    <StackPanel Grid.Row="2"><TextBlock Text="New destination (existing files and folders are preserved)" Margin="0,0,0,5"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="Destination" MinHeight="32" Padding="6"/><Button Grid.Column="1" x:Name="Browse" Content="Browse..." Padding="12,5" Margin="8,0,0,0"/></Grid></StackPanel>
    <StackPanel Grid.Row="3" Margin="0,14,0,0"><CheckBox x:Name="Previews" Content="Include saved thumbnails in HTML pages" IsChecked="True" Margin="0,0,0,10"/><CheckBox x:Name="SafeText" IsChecked="True"><TextBlock Text="Protect spreadsheet text from formulas (adds an apostrophe where needed)" TextWrapping="Wrap"/></CheckBox></StackPanel>
    <StackPanel Grid.Row="4" Margin="0,16,0,0"><WrapPanel><CheckBox x:Name="IncludeEvidence" Content="Also include Evidence details" VerticalAlignment="Center" Margin="0,0,12,0"/><Button x:Name="Unlock" Content="Unlock originals..." Padding="12,5"/></WrapPanel><TextBlock Text="Reports are unencrypted. Including Evidence authenticates stored originals and puts their saved details and optional thumbnails into the plaintext report. Original media bytes are not included." TextWrapping="Wrap" Margin="0,8,0,0" Foreground="#526477"/></StackPanel>
    <TextBlock Grid.Row="5" x:Name="Status" TextWrapping="Wrap" Margin="0,14,0,10"/>
    <StackPanel Grid.Row="6" Orientation="Horizontal" HorizontalAlignment="Center"><Button x:Name="Export" Content="Export report" IsDefault="True" Padding="20,7" Margin="6"/><Button x:Name="Close" Content="Close" IsCancel="True" Padding="20,7" Margin="6"/></StackPanel>
  </Grid>
</Window>
'@
        $w=[Windows.Markup.XamlReader]::Parse($markup);$w.Owner=$u.Window;$u.ReportWindow=$w;$w.FindName('Destination').Text=Join-Path ([IO.Path]::GetDirectoryName($u.Engine.DatabasePath)) 'Media-Review-report.csv'
        $w.FindName('Browse').Add_Click({$w=$script:reviewUi.ReportWindow;if($w.FindName('Format').SelectedIndex -eq 1){$picker=[Windows.Forms.FolderBrowserDialog]::new();$picker.Description='Choose a parent folder. A new report folder will be created inside it.';try{if($picker.ShowDialog() -eq [Windows.Forms.DialogResult]::OK){$w.FindName('Destination').Text=Join-Path $picker.SelectedPath ('Media-Review-report-'+[DateTime]::Now.ToString('yyyyMMdd-HHmmss'))}}finally{$picker.Dispose()}}else{$picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Filter='CSV report (*.csv)|*.csv';$picker.FileName='Media-Review-report.csv';$picker.OverwritePrompt=$false;if($picker.ShowDialog($w)){$w.FindName('Destination').Text=$picker.FileName}}})
        $w.FindName('Format').Add_SelectionChanged({$w=$script:reviewUi.ReportWindow;if($w){$path=$w.FindName('Destination').Text;if($w.FindName('Format').SelectedIndex -eq 1 -and $path.EndsWith('.csv',[StringComparison]::OrdinalIgnoreCase)){$w.FindName('Destination').Text=$path.Substring(0,$path.Length-4)}elseif($w.FindName('Format').SelectedIndex -eq 0 -and -not $path.EndsWith('.csv',[StringComparison]::OrdinalIgnoreCase)){$w.FindName('Destination').Text=$path+'.csv'}}})
        $w.FindName('Unlock').Add_Click({Show-UiVaultDialog});$w.FindName('Export').Add_Click({Start-UiReport});$w.FindName('Close').Add_Click({$script:reviewUi.ReportWindow.Close()});$w.Add_Closed({param($sender,$event) if($script:reviewUi.ReportWindow -eq $sender){$script:reviewUi.ReportWindow=$null}})
    };Update-UiReportControls;$u.ReportWindow.Show();$u.ReportWindow.Activate() | Out-Null
}
function Add-UiReportControls {
    $u=$script:reviewUi;$u | Add-Member -NotePropertyName ReportWindow -NotePropertyValue $null
    $item=[Windows.Controls.MenuItem]::new();$item.Header='Export review report...';$item.Add_Click({Show-UiReport});$u.Controls.MaintenanceButton.ContextMenu.Items.Add($item) | Out-Null
}

function Clear-PackageView($Window){$state=$Window.Tag;$Window.FindName('Picture').Source=$null;$Window.FindName('Details').Text='';$Window.FindName('Placeholder').Text='Select a stored item after unlocking.';if($state.Inspection){$state.Inspection.Dispose();$state.Inspection=$null}}
function Update-PackageControls($Window){$state=$Window.Tag;$session=$state.Session;$ready=$session.Ready -and -not $state.Closing;$idle=$ready -and -not $session.Busy;$unlocked=$ready -and $session.Unlocked
    $Window.FindName('Password').IsEnabled=$idle -and -not $unlocked;$Window.FindName('Unlock').IsEnabled=$idle -and -not $unlocked;$Window.FindName('Lock').IsEnabled=$unlocked;$Window.FindName('Cancel').IsEnabled=$session.Busy -and -not $state.Closing
    $Window.FindName('Items').IsEnabled=$unlocked -and ($idle -or $session.Status.Kind -eq 'Inspect');$Window.FindName('Export').IsEnabled=$idle -and $unlocked -and $state.Inspection -and $state.Inspection.Verified;$Window.FindName('Close').IsEnabled=-not $state.Closing
}
function Apply-PackageResult($Window,[MediaReviewer.PackageResult]$Reply){$state=$Window.Tag;if(-not $Reply.Durable -and ($state.Closing -or $Reply.Generation -ne $state.Generation)){$Reply.Dispose();return $false}
    if(-not $Reply.Success){$Window.FindName('Status').Text=$Reply.Error;Update-PackageControls $Window;return $true}
    if($Reply.Kind -eq 'Unlock'){$Window.FindName('Items').ItemsSource=$Reply.Items}
    if($Reply.Kind -eq 'Inspect'){Clear-PackageView $Window;$state.Inspection=$Reply.Inspection;$Window.FindName('Details').Text=$Reply.Details;$Window.FindName('Picture').Source=$Reply.Inspection.PreviewImage;$Window.FindName('Placeholder').Text=if($Reply.Inspection.PreviewImage){''}elseif($Reply.Inspection.PreviewError){$Reply.Inspection.PreviewError}else{'Saved preview unavailable. The retained original is verified and can be exported.'}}
    $Window.FindName('Status').Text=$Reply.Value;Update-PackageControls $Window;return $true
}
function Invoke-PackageTick($Window){$state=$Window.Tag;if($state.Session.Closed){$state.Timer.Stop();if($state.Session.OutputWarning -and -not $state.CloseWarningShown){$state.CloseWarningShown=$true;[void][Windows.MessageBox]::Show($Window,$state.Session.OutputWarning,'Check incomplete original output',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Warning)};if($Window.IsVisible){$state.AllowClose=$true;$Window.Close()};return}
    $reply=$state.Session.TakeResult();if($reply){[void](Apply-PackageResult $Window $reply)}elseif($state.Session.Busy -or $state.Session.Status.State -in @('failed','cancelled','closing')){$Window.FindName('Status').Text=$state.Session.Status.Stage};Update-PackageControls $Window
}
function Start-PackageOriginalExport($Window,[string]$Destination){$state=$Window.Tag;try{$state.Generation=$state.Session.RequestExport($Window.FindName('Items').SelectedIndex,$Destination);$Window.FindName('Status').Text='Export queued. The verified original will be plaintext at the chosen destination.'}catch{$Window.FindName('Status').Text=$_.Exception.Message};Update-PackageControls $Window}
function New-PackageWindow([string]$Path,$Owner=$null){
    if($script:packageWindow -and -not $script:packageWindow.Tag.Session.Closed){throw 'Close the current protected package before opening another.'}
    $markup=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Protected Evidence package - read only" Width="940" Height="700" MinWidth="700" MinHeight="540" FontFamily="Segoe UI" FontSize="14" WindowStartupLocation="CenterScreen">
 <Grid Margin="16"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="76"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <TextBlock Text="This package opens read only. Unlock to view saved details and thumbnails. Export original writes a verified full-resolution plaintext file only to the destination you choose." TextWrapping="Wrap" Margin="0,0,0,12"/>
  <WrapPanel Grid.Row="1" Margin="0,0,0,12"><TextBlock Text="Originals password" VerticalAlignment="Center" Margin="0,0,8,0"/><PasswordBox VerticalContentAlignment="Center" x:Name="Password" Width="230" MinHeight="32" Padding="5"/><Button x:Name="Unlock" Content="Unlock" Padding="14,5" Margin="8,0,0,0" IsDefault="True"/><Button x:Name="Lock" Content="Lock" Padding="14,5" Margin="8,0,0,0"/><Button x:Name="Cancel" Content="Cancel task" Padding="14,5" Margin="8,0,0,0"/></WrapPanel>
  <Grid Grid.Row="2"><Grid.ColumnDefinitions><ColumnDefinition Width="235"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><ListBox x:Name="Items" HorizontalContentAlignment="Stretch" ScrollViewer.HorizontalScrollBarVisibility="Disabled"/><Grid Grid.Column="1" Margin="12,0,0,0"><Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="190"/></Grid.RowDefinitions><Border Background="#EAF0F5"><Grid><Image x:Name="Picture" Stretch="Uniform"/><TextBlock x:Name="Placeholder" Text="Details remain protected until authentication completes." TextWrapping="Wrap" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="18"/></Grid></Border><TextBox Grid.Row="1" x:Name="Details" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" Margin="0,10,0,0"/></Grid></Grid>
  <TextBlock Grid.Row="3" x:Name="Status" Text="Opening protected package..." TextWrapping="Wrap" VerticalAlignment="Center"/>
  <StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Center"><Button x:Name="Export" Content="Export original..." Padding="20,7" Margin="6"/><Button x:Name="Close" Content="Close" IsCancel="True" Padding="20,7" Margin="6"/></StackPanel>
 </Grid>
</Window>
'@
    $window=[Windows.Markup.XamlReader]::Parse($markup);if($Owner){$window.Owner=$Owner;$window.WindowStartupLocation='CenterOwner'};$session=[MediaReviewer.EvidencePackageSession]::Open($Path);$state=[pscustomobject]@{Session=$session;Generation=[long]0;Inspection=$null;Timer=$null;Closing=$false;AllowClose=$false;CloseWarningShown=$false};$window.Tag=$state;$script:packageWindow=$window
    $window.FindName('Unlock').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);$s=$w.Tag;$bytes=$null;try{$bytes=Get-UiPasswordBytes $w.FindName('Password').SecurePassword;$w.FindName('Password').Clear();$s.Generation=$s.Session.RequestUnlock($bytes);$bytes=$null;$w.FindName('Status').Text='Authenticating package in the background...'}catch{$w.FindName('Status').Text=$_.Exception.Message}finally{if($bytes){[Array]::Clear($bytes,0,$bytes.Length)}};Update-PackageControls $w})
    $window.FindName('Items').Add_SelectionChanged({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);if($sender.SelectedIndex -lt 0 -or -not $w.Tag.Session.Unlocked){return};Clear-PackageView $w;$w.FindName('Placeholder').Text='Loading and verifying stored original...';try{$w.Tag.Generation=$w.Tag.Session.RequestInspect($sender.SelectedIndex);$w.FindName('Status').Text='Authenticating the selected original...'}catch{$w.FindName('Status').Text=$_.Exception.Message};Update-PackageControls $w})
    $window.FindName('Lock').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);Clear-PackageView $w;$w.FindName('Password').Clear();$w.FindName('Items').ItemsSource=$null;try{$w.Tag.Generation=$w.Tag.Session.RequestLock();$w.FindName('Status').Text='Locking package; protected views cleared.'}catch{$w.FindName('Status').Text=$_.Exception.Message};Update-PackageControls $w})
    $window.FindName('Cancel').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);if(-not $w.Tag.Session.Ready){$w.Close()}else{$w.Tag.Session.Cancel();$w.Tag.Generation=$w.Tag.Session.Generation;$w.FindName('Status').Text='Cancelling; waiting for the owned operation.';Update-PackageControls $w}})
    $window.FindName('Export').Add_Click({param($sender,$event) $w=[Windows.Window]::GetWindow($sender);$picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Title='Export verified plaintext original to a new file';$picker.Filter='Original media|*.*';$picker.FileName='Verified-original.bin';$picker.OverwritePrompt=$false;if($picker.ShowDialog($w)){Start-PackageOriginalExport $w $picker.FileName}})
    $window.FindName('Close').Add_Click({param($sender,$event) [Windows.Window]::GetWindow($sender).Close()})
    $window.Add_Closing({param($sender,$event) $s=$sender.Tag;if(-not $s.AllowClose){$event.Cancel=$true;$s.Closing=$true;Clear-PackageView $sender;$sender.FindName('Password').Clear();$sender.FindName('Items').ItemsSource=$null;$s.Session.CloseAsync();Update-PackageControls $sender}})
    $window.Add_Closed({param($sender,$event) $sender.Tag.Timer.Stop();Clear-PackageView $sender;$sender.Tag.Session.CloseAsync();if($script:packageWindow -eq $sender){$script:packageWindow=$null}})
    $timer=[Windows.Threading.DispatcherTimer]::new();$timer.Interval=[TimeSpan]::FromMilliseconds(100);$timer.Tag=$window;$timer.Add_Tick({param($sender,$event) Invoke-PackageTick $sender.Tag});$state.Timer=$timer;$timer.Start();Update-PackageControls $window;return $window
}
function Show-UiPackage([string]$Path){try{if($script:packageWindow -and -not $script:packageWindow.Tag.Session.Closed){$script:packageWindow.Activate() | Out-Null;Set-UiMessage 'Close the current protected package before opening another.';return};$window=New-PackageWindow $Path $script:reviewUi.Window;$window.Show()}catch{Set-UiMessage $_.Exception.Message}}
function Start-PackageInterface([string]$Path){$window=New-PackageWindow $Path;[void]$window.ShowDialog()}
function Invoke-UiPackageExport {
    $u=$script:reviewUi;if(-not $u.Engine -or -not $u.Engine.Ready -or $u.MaintenancePending){return};$cards=@($u.Cards | Where-Object {$_.IsSelected -and -not $_.IsPending});if(-not $cards.Count -or $cards.Count -gt 200){Set-UiMessage 'Select one through 200 Non-compliant or Evidence items with stored originals.';return};if($u.Pending.Count -or ($u.DetailsWindow -and $u.DetailsWindow.Tag.Saving)){Set-UiMessage 'Wait for the pending review to commit before exporting.';return};if(-not $u.Engine.VaultUnlocked){Show-UiVaultDialog ([pscustomobject]@{Kind='Package'});return}
    $picker=[Microsoft.Win32.SaveFileDialog]::new();$picker.Title='Export selected encrypted stored originals';$picker.Filter='Protected Evidence package|*.mcrevidence';$picker.FileName='Media-Review-evidence.mcrevidence';$picker.OverwritePrompt=$false;if($picker.ShowDialog($u.Window)){try{$u.BackgroundOperationId=$u.Engine.RequestEvidencePackageExport([long[]]@($cards | ForEach-Object {$_.Record.GroupId}),$picker.FileName,[Guid]::NewGuid().ToString('N'));$u.MaintenancePending=$true;Set-UiMessage 'Protected package queued. Review changes pause; cached inspection remains available.'}catch{Set-UiMessage $_.Exception.Message};Update-UiControls}
}
function Add-UiPackageControls {
    $u=$script:reviewUi;$item=[Windows.Controls.MenuItem]::new();$item.Header='Export selected protected package...';$item.Add_Click({Invoke-UiPackageExport});$u.Controls.MaintenanceButton.ContextMenu.Items.Add($item) | Out-Null
}

    if($splash){$splash.Close();$splash=$null}
    if($VerifyDependencies){Write-Output ('Verified offline dependencies: SQLite '+[MediaReviewer.Native]::SqliteVersion+'; libvips '+[MediaReviewer.Native]::DecoderVersion+'; Windows CNG; PowerShell '+$PSVersionTable.PSVersion);return}
    if($ScanPath -or $ResumeScanId -or $ImportHtmlPath){
        if(-not $DatabasePath){throw 'A command-line scan or import requires -DatabasePath.'}
        if($ImportHtmlPath -and ($ScanPath -or $ResumeScanId -or $CreateDatabase)){throw 'Use -ImportHtmlPath with a new -DatabasePath; scanning and -CreateDatabase are separate operations.'}
        $engine=if($ImportHtmlPath){[MediaReviewer.ReviewerEngine]::ImportHtml($ImportHtmlPath,$DatabasePath)}else{[MediaReviewer.ReviewerEngine]::Open($DatabasePath,[bool]$CreateDatabase)}
        $openingLast=[DateTime]::MinValue
        while(-not $engine.Ready -and -not $engine.Faulted){if(([DateTime]::UtcNow-$openingLast).TotalSeconds -ge 1){Write-Output $engine.Status.Stage;$openingLast=[DateTime]::UtcNow};Start-Sleep -Milliseconds 25}
        if($engine.Faulted){throw $engine.Status.Error}
        if($ImportHtmlPath){Write-Output ('Imported final HTML database: '+$engine.DatabasePath);return}
        if($ResumeScanId){$engine.ResumeScan($ResumeScanId,$WorkerCount)}else{$options=[MediaReviewer.ScanOptions]::new();$options.RootPath=$ScanPath;$options.WorkerCount=$WorkerCount;$options.ScanArchives=[bool]$ScanArchives;if($Extensions){$options.Extensions=[string[]]@($Extensions|ForEach-Object{$_ -split '[,;\s]+'}|Where-Object{$_})}elseif($ScanMode -eq 'Deep'){$options.Extensions=[MediaReviewer.Formats]::Deep;$options.ExcludeApplicationData=$false}elseif($ScanMode -eq 'Custom'){throw 'Custom command-line scans require -Extensions.'};$engine.StartScan($options) | Out-Null}
        $last=[DateTime]::MinValue
        while($engine.Status.RunningScan){if(([DateTime]::UtcNow-$last).TotalSeconds -ge 1){$status=$engine.Status;Write-Output ($status.Stage+'; committed files '+$status.ProcessedFiles+'; pending '+$status.PendingWork);$last=[DateTime]::UtcNow};Start-Sleep -Milliseconds 50}
        $status=$engine.Status;Write-Output ($status | ConvertTo-Json -Compress)
        if($engine.Faulted -or $status.Error){throw $status.Error}
        return
    }
    if($OpenEvidencePackage){Start-PackageInterface $OpenEvidencePackage}else{Start-ReviewerInterface}
} catch {
    $failure=$_.Exception.Message;Write-StartupDiagnostic ($_.Exception.ToString());$savedDiagnostic=Save-ReviewerDiagnostic $startupDiagnosticPath $failure;$diagnosticNotice=if($savedDiagnostic){'Startup diagnostic: '+$savedDiagnostic}else{'Startup diagnostic could not be preserved.'};Write-Output $diagnosticNotice
    if($splash){$splash.FindName('Stage').Text=$_.Exception.Message;$splash.Close()}
    if(('Windows.MessageBox' -as [type]) -and -not $VerifyDependencies -and -not $ScanPath -and -not $ResumeScanId -and -not $ImportHtmlPath){[Windows.MessageBox]::Show(($failure+"`r`n`r`n"+$diagnosticNotice),'Media Compliance Reviewer could not start',[Windows.MessageBoxButton]::OK,[Windows.MessageBoxImage]::Error) | Out-Null}
    throw [InvalidOperationException]::new(($failure+"`r`n`r`n"+$diagnosticNotice),$_.Exception)
} finally {
    try{if($engine){$engine.Dispose()}}finally{
        try{if('MediaReviewer.Preview' -as [type]){[MediaReviewer.Preview]::Shutdown()}}finally{
            foreach($name in @('TEMP','TMP','TMPDIR')){[Environment]::SetEnvironmentVariable($name,$originalTemp[$name],'Process')}
            # Embedded fixtures retain their lease until their host exits, just like loaded assemblies.
            if(-not $embeddedRuntime){$instanceLease.Dispose()}
        }
    }
}

